export const NPC_DATABASE: Record<string, NPC> = {
  'wuher': {
    id: 'wuher', name: 'Wuher', imageUrl: IMAGES.NPC_WUHER, greetingId: 'intro',
    dialogueTree: {
      'intro': { 
          id: 'intro', 
          text: "I saw you tuck that Imperial datapad away when the patrol walked in. Don't worry, I haven't summoned them... yet. But silence isn't free.", 
          options: [
              { label: 'Just a drink (5 credits).', nextId: 'drink', action: (g: any) => { if (g.credits >= 5) { g.setCredits((c:number) => c - 5); g.addToLog("You enjoy a refreshing drink."); } else { g.addToLog("You can't afford a drink."); } } }, 
