export const OpeningCrawl: React.FC<{ onFinished: () => void, volume: number }> = ({ onFinished, volume }) => {
    const [phase, setPhase] = useState<'intro' | 'crawl'>('intro');
    const [audioPlaying, setAudioPlaying] = useState(false);
    const [isFadingOut, setIsFadingOut] = useState(false);
    const [isFadingIn, setIsFadingIn] = useState(true);
    const [internalVolume, setInternalVolume] = useState(volume);

    useEffect(() => {
        const timer = setTimeout(() => {
            setIsFadingIn(false);
        }, 100);
        return () => clearTimeout(timer);
    }, []);

    useEffect(() => {
        const introTimer = setTimeout(() => {
            setPhase('crawl');
            setAudioPlaying(true);
        }, 4000);

        return () => clearTimeout(introTimer);
    }, []);

    useEffect(() => {
        if (!isFadingOut) setInternalVolume(volume);
    }, [volume, isFadingOut]);

    const handleSkip = () => {
        if (isFadingOut) return;
        setIsFadingOut(true);
        const fadeDuration = 2000;
        const steps = 40; 
        const stepTime = fadeDuration / steps; 

        const fadeInterval = setInterval(() => {
            setInternalVolume(prev => Math.max(0, prev - (volume / steps)));
        }, stepTime);

        setTimeout(() => {
            clearInterval(fadeInterval);
            onFinished();
        }, fadeDuration);
    };

    useEffect(() => {
        if (phase === 'crawl') {
            const finishTimer = setTimeout(handleSkip, 90000);
            return () => clearTimeout(finishTimer);
        }
    }, [phase]);

    return (
        <div className={`fixed inset-0 bg-black z-[50] overflow-hidden transition-opacity duration-[2000ms] ease-in-out ${isFadingOut ? 'opacity-0' : (isFadingIn ? 'opacity-0' : 'opacity-100')}`} style={{
            backgroundImage: 'url(https://i.postimg.cc/qRtKmN94/eae041e8872e2b60068958ee0ee38884.jpg)', 
            backgroundSize: 'cover', 
            backgroundPosition: 'center'
        }}>
            <div className="absolute inset-0 bg-black/40 pointer-events-none" />
            <BackgroundAudioPlayer src={AUDIO.MAIN_TITLE} volume={internalVolume} isPlaying={audioPlaying} loop={false} />
            {phase === 'intro' && (
                <div className="absolute inset-0 flex items-center justify-center z-20">
                     <h1 className="text-[#4bd5ee] text-lg md:text-2xl font-sans tracking-widest select-none opacity-0 drop-shadow-md"
                         style={{ animation: 'introFade 4s ease-in-out forwards' }}>
                        A long time ago in a galaxy far, far away....
                    </h1>
                </div>
            )}
            {phase === 'crawl' && (
                <div id="sw-overlay" style={{ width: '100%', height: '100%', position: 'absolute', top: 0, left: 0, zIndex: 10 }}>
                    <div id="sw-fade" />
                    <div id="sw-perspective">
                        <div id="sw-content">
                            <h1>Episode I</h1>
                            <h2>THE OUTER RIM</h2>
                            <p>It is a dark time for the galaxy. The GALACTIC EMPIRE has tightened its grip, crushing the last remnants of the Old Republic. Fear keeps the local systems in line.</p>
                            <p>In the lawless sectors of the Outer Rim, criminal syndicates and corrupt Moffs vie for control. It is a haven for smugglers, bounty hunters, and those wishing to disappear.</p>
                            <p>You have found yourself stranded on the desert world of TATOOINE. In your possession is a stolen Imperial datapad, encrypted with codes that could spark a rebellion or buy a king's ransom.</p>
                            <p>With Imperial ISB agents closing in and local gangs hungry for a payout, you must navigate the wretched hives of scum and villainy to survive. Your ship, the <i>Rusty Mynock</i>, is grounded. Your credits are running low.</p>
                            <p>The twin suns beat down on the sand. Destiny calls from the dunes...</p>
                        </div>
                    </div>
                    <button onClick={handleSkip} className="absolute bottom-5 right-5 z-50 text-yellow-400 border border-yellow-400 px-4 py-2 uppercase font-sans text-xs tracking-widest hover:bg-yellow-400/20">Skip Intro</button>
                </div>
            )}
            <style>{`
                @keyframes introFade { 0% { opacity: 0; } 15% { opacity: 1; } 85% { opacity: 1; } 100% { opacity: 0; } }
                #sw-overlay { color: #feda4a; font-family: "Franklin Gothic Medium", "Arial Narrow", Arial, sans-serif; }
                #sw-fade { position: absolute; top: 0; left: 0; right: 0; height: 20vh; background: linear-gradient(to bottom, #000 0%, transparent 100%); z-index: 10; pointer-events: none; }
                #sw-perspective { position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; justify-content: center; }
                #sw-content { position: absolute; top: 100%; width: 50%; left: 0; right: 0; margin: 0 auto; text-align: justify; font-weight: 700; font-size: 500%; line-height: 1.35em; letter-spacing: 0.05em; animation: sw-scroll 90s linear forwards; transform-origin: 50% 100%; transform: rotateX(30deg); padding: 0 2%; box-sizing: border-box; }
                #sw-content h1 { text-align: center; font-family: 'Cinzel', serif; font-size: 1.5em; margin-bottom: 0.5em; line-height: 1em; font-weight: normal; width: 100%; }
                #sw-content h2 { text-align: center; font-family: 'Cinzel', serif; font-size: 5em; text-transform: uppercase; margin-bottom: 0.5em; line-height: 1em; width: 100%; }
                #sw-content p { margin-bottom: 2em; }
                @keyframes sw-scroll { 0% { top: 100%; opacity: 1; } 95% { opacity: 1; } 100% { top: -200%; opacity: 0; } }
                @media screen and (max-width: 768px) { #sw-content { font-size: 130%; width: 90%; left: 5%; padding: 0; transform: rotateX(30deg); animation: sw-scroll 90s linear forwards; } #sw-content h1 { font-size: 2em; margin-bottom: 0.25em; } #sw-content h2 { font-size: 3em; margin-bottom: 0.5em; } #sw-content p { margin-bottom: 1.5em; } }
            `}</style>
        </div>
    );
};

