export const CharacterCreator: React.FC<{ onFinished: (character: Character) => void }> = ({ onFinished }) => {
    const [name, setName] = useState('');
    const [selectedRaceId, setSelectedRaceId] = useState<string>(RACES[0].id);
    const [selectedClassId, setSelectedClassId] = useState<string>(CLASSES[0].id);
    const [opacity, setOpacity] = useState(0);
    const [audioVolume, setAudioVolume] = useState(0);

    useEffect(() => {
        const timer = setTimeout(() => setOpacity(1), 100);
        return () => clearTimeout(timer);
    }, []);

    useEffect(() => {
        const duration = 2000;
        const interval = 50;
        const targetVolume = 0.3;
        const steps = duration / interval;
        const stepAmount = targetVolume / steps;

        const timer = setInterval(() => {
            setAudioVolume(prev => {
                const next = prev + stepAmount;
                if (next >= targetVolume) {
                    clearInterval(timer);
                    return targetVolume;
                }
                return next;
            });
        }, interval);
        return () => clearInterval(timer);
    }, []);

    const handleFinish = () => {
        if (!name.trim()) return;
        const race = RACES.find(r => r.id === selectedRaceId)!;
        const charClass = CLASSES.find(c => c.id === selectedClassId)!;
        const baseStats: Stats = { str: 5, per: 5, end: 5, cha: 5, int: 5, agi: 5, lck: 5 };
        const finalStats = { ...baseStats };
        (Object.keys(race.bonuses) as Array<keyof Stats>).forEach(key => { finalStats[key] += race.bonuses[key]!; });
        (Object.keys(charClass.bonuses) as Array<keyof Stats>).forEach(key => { finalStats[key] += charClass.bonuses[key]!; });
        const maxHp = 20 + (finalStats.end * 2);
        onFinished({ name, race, charClass, stats: finalStats, maxHp, currentHp: maxHp, background: "A mysterious past finds you on the Outer Rim...", party: [] });
    };

    const selectedRace = RACES.find(r => r.id === selectedRaceId);
    const selectedClass = CLASSES.find(c => c.id === selectedClassId);

    return (
        <div className={`w-full h-full bg-cover bg-center overflow-y-auto transition-opacity duration-[2000ms] ease-in-out ${opacity ? 'opacity-100' : 'opacity-0'}`} style={{ backgroundImage: `url(${IMAGES.CREATION})` }}>
            <BackgroundAudioPlayer src={AUDIO.MENU_THEME} volume={audioVolume} isPlaying={true} loop={true} />
            <div className="min-h-full flex flex-col justify-center items-center p-4">
                <div className="w-full max-w-4xl text-white">
                    <h1 className="text-4xl text-yellow-400 mb-6 text-center font-title title-outline">IDENTITY RECORD</h1>
                    <div className="flex flex-col gap-4">
                        <div className="hud-panel p-4 bg-black/50 border border-cyan-800"><label className="block text-cyan-400 mb-2 font-display">CALLSIGN:</label><input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full p-2 bg-black/50 border border-cyan-700 focus:outline-none focus:ring-2 focus:ring-cyan-400" /></div>
                        <div className="hud-panel p-4 bg-black/50 border border-cyan-800"><label className="block text-cyan-400 mb-2 font-display">BIOLOGICAL SCAN (RACE):</label><select value={selectedRaceId} onChange={e => setSelectedRaceId(e.target.value)} className="w-full p-2 bg-black/50 border border-cyan-700">{RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}</select></div>
                        <div className="hud-panel p-4 bg-black/50 border border-cyan-800"><label className="block text-cyan-400 mb-2 font-display">PRIMARY TRAINING (CLASS):</label><select value={selectedClassId} onChange={e => setSelectedClassId(e.target.value)} className="w-full p-2 bg-black/50 border border-cyan-700">{CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div>
                        <div className="hud-panel p-4 bg-black/50 border border-cyan-800"><h2 className="text-xl text-cyan-300 font-display border-b border-cyan-700 pb-2 mb-4">DATA READOUT</h2>{selectedRace && (<div className="mb-4"><h3 className="font-bold text-lg text-yellow-400">{selectedRace.name}</h3><p className="text-sm text-gray-300">{selectedRace.description}</p></div>)}{selectedClass && (<div className="mb-4"><h3 className="font-bold text-lg text-yellow-400">{selectedClass.name}</h3><p className="text-sm text-gray-300">{selectedClass.description}</p></div>)}{selectedClass?.startingItem && (<div className="mt-4"><h4 className="text-cyan-400 font-display">Starting Gear:</h4><p className="text-sm text-gray-200">{selectedClass.startingItem.name}</p></div>)}</div>
                        <CommandButton label="FINALIZE RECORD" onClick={handleFinish} disabled={!name.trim()} className="w-full text-xl py-2 font-display text-center" />
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { createSabaccDeck, calculateHandValue, SabaccCard } from '../utils';
import { CommandButton } from './Shared';

// --- SLICING GAME ---
export const SlicingGame: React.FC<{ 
    difficulty: 'easy' | 'medium' | 'hard';
    onWin: () => void;
    onLose: () => void;
    onClose: () => void;
}> = ({ difficulty, onWin, onLose, onClose }) => {
    const config = {
        easy: { stages: 2, tolerance: 30, speed: 20 },
        medium: { stages: 3, tolerance: 20, speed: 30 },
        hard: { stages: 4, tolerance: 10, speed: 45 }
    }[difficulty];

    const [stage, setStage] = useState(0);
    const [position, setPosition] = useState(50);
    const [direction, setDirection] = useState(1);
    const [target, setTarget] = useState(50);
    const [locked, setLocked] = useState(false);
    const [status, setStatus] = useState<'playing' | 'won' | 'lost'>('playing');

    const requestRef = useRef<number>(0);

    // Randomize target on mount and stage change
    useEffect(() => {
        setTarget(Math.random() * 80 + 10); // Keep target between 10% and 90%
        setLocked(false);
    }, [stage]);

    // Animation Loop
    useEffect(() => {
        if (status !== 'playing' || locked) return;

        const animate = () => {
            setPosition(prev => {
                let next = prev + (direction * (config.speed * 0.05));
                if (next >= 100) {
                    next = 100;
                    setDirection(-1);
                } else if (next <= 0) {
                    next = 0;
                    setDirection(1);
                }
                return next;
            });
            requestRef.current = requestAnimationFrame(animate);
        };

        requestRef.current = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(requestRef.current);
    }, [direction, config.speed, status, locked]);

    const handleLock = () => {
        if (locked || status !== 'playing') return;
        setLocked(true);
        const diff = Math.abs(position - target);

        if (diff <= config.tolerance / 2) {
            // Hit
            setTimeout(() => {
                if (stage + 1 >= config.stages) {
                    setStatus('won');
                    setTimeout(onWin, 1000);
                } else {
                    setStage(s => s + 1);
                }
            }, 500);
        } else {
            // Miss
            setStatus('lost');
            setTimeout(onLose, 1000);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
            <div className="bg-gray-900 border-2 border-cyan-500 p-8 rounded-lg w-full max-w-md shadow-[0_0_20px_rgba(6,182,212,0.5)]">
                <h2 className="text-2xl font-title text-cyan-400 mb-2 text-center">SECURITY OVERRIDE</h2>
                <div className="text-xs font-mono text-cyan-700 mb-6 text-center">Protocol: {difficulty.toUpperCase()} // Stage {stage + 1}/{config.stages}</div>

                <div className="relative h-12 bg-gray-800 rounded border border-cyan-800 mb-8 overflow-hidden">
                    {/* Target Zone */}
                    <div 
                        className="absolute top-0 bottom-0 bg-cyan-900/50 border-x border-cyan-500/50"
                        style={{ 
                            left: `${target - (config.tolerance / 2)}%`, 
                            width: `${config.tolerance}%` 
                        }}
                    />

                    {/* Cursor */}
                    <div 
                        className={`absolute top-0 bottom-0 w-1 transition-colors duration-100 ${status === 'lost' ? 'bg-red-500 shadow-[0_0_10px_red]' : (status === 'won' ? 'bg-green-400 shadow-[0_0_10px_lime]' : 'bg-white shadow-[0_0_10px_white]')}`}
                        style={{ left: `${position}%` }}
                    />
                </div>

                <div className="flex justify-center gap-4">
                    {status === 'playing' ? (
                        <button 
                            onMouseDown={handleLock}
                            className="bg-cyan-600 hover:bg-cyan-500 text-black font-bold py-3 px-8 rounded font-display w-full tracking-wider"
                        >
                            LOCK FREQUENCY
                        </button>
                    ) : (
                        <div className={`text-center font-title text-2xl ${status === 'won' ? 'text-green-400' : 'text-red-500'}`}>
                            {status === 'won' ? 'ACCESS GRANTED' : 'ACCESS DENIED'}
                        </div>
                    )}
                </div>
                {status !== 'playing' && status === 'lost' && (
                    <div className="mt-4 flex justify-center">
                        <CommandButton label="Close" onClick={onClose} />
                    </div>
                )}
            </div>
        </div>
    );
};

// --- SABACC GAME ---
export const SabaccGame: React.FC<{
    onClose: () => void;
    onFinish: (result: 'win' | 'lose' | 'draw', amount: number) => void;
    betAmount: number;
}> = ({ onClose, onFinish, betAmount }) => {
    const [deck, setDeck] = useState<SabaccCard[]>([]);
    const [playerHand, setPlayerHand] = useState<SabaccCard[]>([]);
    const [enemyHand, setEnemyHand] = useState<SabaccCard[]>([]);
    const [phase, setPhase] = useState<'deal' | 'action' | 'reveal'>('deal');
    const [pot, setPot] = useState(betAmount * 2);
    const [msg, setMsg] = useState("Dealing cards...");

    // Init
    useEffect(() => {
        startRound();
    }, []);

    const startRound = () => {
        const newDeck = createSabaccDeck();
        const pHand = [newDeck.pop()!, newDeck.pop()!];
        const eHand = [newDeck.pop()!, newDeck.pop()!];

        setDeck(newDeck);
        setPlayerHand(pHand);
        setEnemyHand(eHand);
        setPhase('action');
        setMsg("Your turn. Draw a card or Stand?");
    };

    const drawCard = () => {
        if (phase !== 'action') return;
        const newDeck = [...deck];
        const card = newDeck.pop();
        if (card) {
            setPlayerHand([...playerHand, card]);

            // Enemy AI (Simple)
            const eVal = calculateHandValue(enemyHand);
            // Enemy draws if they are far from 0 or positive Sabacc, and hand size < 5
            if (Math.abs(eVal.sum) > 5 && enemyHand.length < 5) {
                const eCard = newDeck.pop();
                if(eCard) setEnemyHand(prev => [...prev, eCard]);
            }
        }
        setDeck(newDeck);
        setPhase('reveal');
    };

    const stand = () => {
         // Enemy AI (Simple) check draw even if player stands
         const newDeck = [...deck];
         const eVal = calculateHandValue(enemyHand);
         if (Math.abs(eVal.sum) > 5 && enemyHand.length < 5) {
             const eCard = newDeck.pop();
             if(eCard) setEnemyHand(prev => [...prev, eCard]);
             setDeck(newDeck);
         }
         setPhase('reveal');
    };

    const determineWinner = () => {
        const pScore = calculateHandValue(playerHand);
        const eScore = calculateHandValue(enemyHand);

        let result: 'win' | 'lose' | 'draw' = 'draw';

        if (pScore.rank === -1 && eScore.rank === -1) result = 'draw'; // Both bomb
        else if (pScore.rank === -1) result = 'lose';
        else if (eScore.rank === -1) result = 'win';
        else if (pScore.rank > eScore.rank) result = 'win';
        else if (eScore.rank > pScore.rank) result = 'lose';
        else result = 'draw';

        if (result === 'win') {
            setMsg(`You Win! ${pScore.label} beats ${eScore.label}`);
            setTimeout(() => onFinish('win', pot), 3000);
        } else if (result === 'lose') {
            setMsg(`Defeat. ${eScore.label} beats ${pScore.label}`);
            setTimeout(() => onFinish('lose', 0), 3000);
        } else {
            setMsg(`Draw. Pot returned.`);
            setTimeout(() => onFinish('draw', betAmount), 3000);
        }
    };

    useEffect(() => {
        if (phase === 'reveal') {
            determineWinner();
        }
    }, [phase]);

    const pScore = calculateHandValue(playerHand);

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md">
            <div className="w-full max-w-4xl h-[90vh] flex flex-col p-4">
                {/* Header */}
                <div className="flex justify-between items-center border-b border-gray-700 pb-4 mb-4">
                    <h2 className="text-3xl font-title text-yellow-500">SABACC TABLE</h2>
                    <div className="text-xl font-display text-cyan-400">POT: {pot} Credits</div>
                </div>

                {/* Game Area */}
                <div className="flex-1 flex flex-col justify-between">

                    {/* Enemy Area */}
                    <div className="flex flex-col items-center">
                        <div className="text-gray-400 mb-2 font-display">OPPONENT</div>
                        <div className="flex gap-2">
                            {enemyHand.map((card, idx) => (
                                <div key={idx} className={`w-24 h-36 rounded border-2 flex items-center justify-center bg-gray-800 ${phase === 'reveal' ? (card.color === 'green' ? 'border-green-600 text-green-400' : card.color === 'red' ? 'border-red-600 text-red-400' : 'border-white text-white') : 'border-gray-600'}`}>
                                    {phase === 'reveal' ? (
                                        <div className="text-center">
                                            <div className="text-2xl font-bold">{card.val}</div>
                                            <div className="text-xs uppercase mt-1">{card.suit}</div>
                                        </div>
                                    ) : (
                                        <div className="w-full h-full bg-stripes-gray opacity-20" />
                                    )}
                                </div>
                            ))}
                        </div>
                        {phase === 'reveal' && <div className="mt-2 text-xl font-mono text-white">{calculateHandValue(enemyHand).label}</div>}
                    </div>

                    {/* Message Area */}
                    <div className="text-center py-8">
                        <div className="inline-block px-6 py-2 bg-black border border-yellow-500/50 text-yellow-400 font-display text-lg rounded shadow-[0_0_15px_rgba(234,179,8,0.2)]">
                            {msg}
                        </div>
                    </div>

                    {/* Player Area */}
                    <div className="flex flex-col items-center">
                         <div className="flex gap-2 mb-4">
                            {playerHand.map((card, idx) => (
                                <div key={idx} className={`w-24 h-36 rounded border-2 flex items-center justify-center bg-gray-900 ${card.color === 'green' ? 'border-green-500 text-green-400 shadow-[0_0_10px_rgba(74,222,128,0.2)]' : card.color === 'red' ? 'border-red-500 text-red-400 shadow-[0_0_10px_rgba(248,113,113,0.2)]' : 'border-white text-white'}`}>
                                    <div className="text-center transform transition-transform hover:scale-110">
                                        <div className="text-4xl font-bold font-title">{card.val}</div>
                                        <div className="text-xs uppercase mt-2 tracking-widest opacity-80">{card.suit}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="text-2xl font-mono text-cyan-300 mb-6 drop-shadow-md">Current Hand: {pScore.label}</div>

                        {phase === 'action' && (
                            <div className="flex gap-4">
                                <CommandButton 
                                    label="DRAW CARD" 
                                    onClick={drawCard} 
                                    className="text-lg px-8 py-4 border-green-500/50 hover:bg-green-900/30 text-green-400"
                                    disabled={playerHand.length >= 5}
                                />
                                <CommandButton 
                                    label="STAND" 
                                    onClick={stand} 
                                    className="text-lg px-8 py-4 border-yellow-500/50 hover:bg-yellow-900/30 text-yellow-400"
                                />
                            </div>
                        )}
                        <div className="text-gray-400 mt-2 text-sm font-display">PLAYER</div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Character, Quest, Item, SaveData, Locations, Location, DialogueNode } from '../types';
import { IMAGES, NPC_DATABASE, ITEM_DATABASE } from '../data';
import { Typewriter, CommandButton } from './Shared';
import { SlicingGame, SabaccGame } from './Minigames';

interface DashboardProps {
    gameState: SaveData;
    setGameState: React.Dispatch<React.SetStateAction<SaveData>>;
    locations: Locations;
    onSave: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ gameState, setGameState, locations, onSave }) => {
    const [dialogueNode, setDialogueNode] = useState<DialogueNode | null>(null);
    const [currentNpcId, setCurrentNpcId] = useState<string | null>(null);
    const [activeMinigame, setActiveMinigame] = useState<'slicing' | 'sabacc' | null>(null);
    const [slicingTarget, setSlicingTarget] = useState<string | null>(null);
    const [logKey, setLogKey] = useState(0);

    const currentLocation = locations[gameState.currentLocationId];
    const isNight = gameState.isNight;

    // Derived values based on Time of Day
    const locName = isNight ? (currentLocation.nightName || currentLocation.name) : currentLocation.name;
    const locDesc = isNight ? (currentLocation.nightDescription || currentLocation.description) : currentLocation.description;
    const locImg = isNight ? (currentLocation.nightImageUrl || currentLocation.imageUrl) : currentLocation.imageUrl;
    const locExits = isNight ? (currentLocation.nightExits || currentLocation.exits) : currentLocation.exits;
    const locNpcs = isNight ? (currentLocation.nightNpcs || currentLocation.npcs || []) : (currentLocation.npcs || []);
    const locActions = isNight ? (currentLocation.nightActions || currentLocation.actions || []) : (currentLocation.actions || []);
    const locSearchables = isNight ? (currentLocation.nightSearchables || currentLocation.searchables || []) : (currentLocation.searchables || []);
    const locAmbient = currentLocation.ambient || [];

    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [gameState.history, logKey]);

    const addToLog = (text: string) => {
        setGameState(prev => ({
            ...prev,
            history: [...prev.history, text].slice(-50) // Keep last 50 lines
        }));
        setLogKey(k => k + 1);
    };

    // --- ACTIONS ---

    const handleMove = (exitId: string) => {
        const nextLoc = locations[exitId];
        if (!nextLoc) return;

        setDialogueNode(null);
        setCurrentNpcId(null);

        setGameState(prev => {
            const visited = prev.visitedLocations.includes(exitId);
            const newHistory = [...prev.history];

            // Add description to log if first visit
            if (!visited && nextLoc.firstVisitDescription) {
                // We'll handle this log addition in the effect or just here
            }

            return {
                ...prev,
                currentLocationId: exitId,
                visitedLocations: visited ? prev.visitedLocations : [...prev.visitedLocations, exitId]
            };
        });
    };

    const handleRest = () => {
        setGameState(prev => ({
            ...prev,
            isNight: !prev.isNight,
            stats: prev.stats ? { ...prev.stats, currentHp: prev.stats.maxHp } : null
        }));
        addToLog(isNight ? "You sleep until morning. The suns rise over the dunes." : "You rest until evening. The air cools down.");
    };

    const handleAction = (action: string) => {
        if (action === 'Look Around') {
            const detailed = isNight ? (currentLocation.nightDetailedDescription || currentLocation.detailedDescription) : currentLocation.detailedDescription;
            addToLog(detailed || "You see nothing unusual.");

            // Trigger chance encounters
            if (currentLocation.encounters) {
                const roll = Math.random();
                const encounter = currentLocation.encounters.find(e => {
                    if (e.onlyNight && !isNight) return false;
                    if (e.onlyDay && isNight) return false;
                    return roll < e.chance;
                });

                if (encounter) {
                    addToLog(`> ${encounter.description}`);
                    if (encounter.lootDescription && encounter.lootLabel) {
                         // Simplify: Just give loot immediately for this demo logic
                         addToLog(`You found: ${encounter.lootDescription}`);
                         if (encounter.credits) {
                             setGameState(prev => ({ ...prev, credits: prev.credits + encounter.credits! }));
                             addToLog(`+${encounter.credits} Credits`);
                         }
                         if (encounter.item) {
                             const itemObj = ITEM_DATABASE.find(i => i.id === encounter.item);
                             if (itemObj) {
                                 setGameState(prev => ({ ...prev, inventory: [...prev.inventory, itemObj] }));
                                 addToLog(`Received: ${itemObj.name}`);
                             }
                         }
                    }
                }
            }
        } 
        else if (action === 'Play Sabacc') {
            if (gameState.credits < 10) {
                addToLog("You need at least 10 credits to play.");
                return;
            }
            setActiveMinigame('sabacc');
        }
        else if (action === 'Rest (Heal)') {
            handleRest();
        }
        else if (action === 'Collect Daily Stipend') {
             if (!gameState.dailyStipendClaimed) {
                 setGameState(prev => ({ ...prev, credits: prev.credits + 50, dailyStipendClaimed: true }));
                 addToLog("Guild Stipend Collected: 50 Credits.");
             } else {
                 addToLog("You have already collected your stipend for today.");
             }
        }
    };

    const handleSearch = (searchableId: string) => {
        const target = locSearchables.find(s => s.id === searchableId);
        if (!target) return;

        // Check if already looted/unlocked
        if (gameState.lootedContainers.includes(searchableId)) {
            addToLog("Empty.");
            return;
        }

        // Check requirements
        if (target.reqQuestState) {
            const quest = gameState.quests.find(q => q.id === target.reqQuestState!.id);
            if (!quest || quest.currentStepIndex < target.reqQuestState.step) {
                addToLog("You don't see anything of interest yet.");
                return;
            }
        }

        if (target.locked && !gameState.unlockedContainers.includes(searchableId)) {
            setSlicingTarget(searchableId);
            setActiveMinigame('slicing');
            return;
        }

        // Success
        addToLog(target.description);
        if (target.credits) {
            setGameState(prev => ({ ...prev, credits: prev.credits + target.credits! }));
            addToLog(`+${target.credits} Credits`);
        }
        if (target.item) {
            const itemObj = ITEM_DATABASE.find(i => i.id === target.item);
            if (itemObj) {
                setGameState(prev => ({ ...prev, inventory: [...prev.inventory, itemObj] }));
                addToLog(`Found: ${itemObj.name}`);
            }
        }

        // Quest Updates
        if (target.questUpdate) {
             setGameState(prev => ({
                 ...prev,
                 quests: prev.quests.map(q => q.id === target.questUpdate!.id ? { ...q, currentStepIndex: target.questUpdate!.step } : q)
             }));
             addToLog("Quest Updated.");
        }

        setGameState(prev => ({ ...prev, lootedContainers: [...prev.lootedContainers, searchableId] }));
    };

    // --- DIALOGUE ---

    const startDialogue = (npcId: string) => {
        const npc = NPC_DATABASE[npcId];
        if (!npc) return;
        setCurrentNpcId(npcId);

        // Determine greeting based on conditions (not fully impl in this demo, defaulting to 'intro')
        const greetingId = (isNight && npc.nightGreetingId) ? npc.nightGreetingId : npc.greetingId;
        setDialogueNode(npc.dialogueTree[greetingId]);
    };

    const handleDialogueOption = (opt: any) => {
        if (opt.action) {
            // Create a proxy for gameState mutations
            const gameProxy = {
                credits: gameState.credits,
                setCredits: (fn: any) => setGameState(prev => ({ ...prev, credits: fn(prev.credits) })),
                addToLog: addToLog,
                updateQuest: (qid: string, step: number) => setGameState(prev => ({ ...prev, quests: prev.quests.map(q => q.id === qid ? { ...q, currentStepIndex: step } : q) })),
                completeQuest: (qid: string) => setGameState(prev => ({ ...prev, quests: prev.quests.map(q => q.id === qid ? { ...q, status: 'completed' } : q) })),
                setInventory: (fn: any) => setGameState(prev => ({ ...prev, inventory: fn(prev.inventory) })),
                setStats: (fn: any) => setGameState(prev => ({ ...prev, stats: fn(prev.stats) })),
                setQuests: (fn: any) => setGameState(prev => ({ ...prev, quests: fn(prev.quests) })),
                setDefeatedNpcs: (fn: any) => setGameState(prev => ({ ...prev, defeatedNpcs: fn(prev.defeatedNpcs) })),
            };
            opt.action(gameProxy);
        }

        if (opt.nextId) {
            const npc = NPC_DATABASE[currentNpcId!];
            setDialogueNode(npc.dialogueTree[opt.nextId]);
        } else {
            setDialogueNode(null);
            setCurrentNpcId(null);
        }
    };

    // --- RENDER HELPERS ---

    const renderMinigame = () => {
        if (activeMinigame === 'slicing') {
            return (
                <SlicingGame 
                    difficulty="medium"
                    onClose={() => setActiveMinigame(null)}
                    onWin={() => {
                        setActiveMinigame(null);
                        setGameState(prev => ({ ...prev, unlockedContainers: [...prev.unlockedContainers, slicingTarget!] }));
                        addToLog("Access Granted. Security systems bypassed.");
                        // Auto-loot after unlock
                        handleSearch(slicingTarget!);
                    }}
                    onLose={() => {
                        setActiveMinigame(null);
                        addToLog("Slicing failed. Security lockout engaged.");
                    }}
                />
            );
        }
        if (activeMinigame === 'sabacc') {
            return (
                <SabaccGame 
                    betAmount={10}
                    onClose={() => setActiveMinigame(null)}
                    onFinish={(result, amount) => {
                        setActiveMinigame(null);
                        if (result === 'win') {
                            setGameState(prev => ({ ...prev, credits: prev.credits + amount }));
                            addToLog(`You won the hand! gained ${amount} credits.`);
                        } else if (result === 'lose') {
                            setGameState(prev => ({ ...prev, credits: prev.credits - 10 })); // Lost bet
                            addToLog("You lost the hand.");
                        } else {
                            addToLog("Draw. Credits returned.");
                        }
                    }}
                />
            );
        }
        return null;
    };

    return (
        <div className="flex flex-col md:flex-row h-full w-full max-w-7xl mx-auto md:p-4 gap-4 text-cyan-100 font-sans text-sm md:text-base">
            {renderMinigame()}

            {/* LEFT COLUMN - STATS */}
            <div className="w-full md:w-1/4 flex flex-col gap-4 order-2 md:order-1 h-1/4 md:h-full overflow-hidden">
                <div className="bg-gray-900/80 border border-cyan-700 p-4 rounded h-full overflow-y-auto no-scrollbar relative shadow-[0_0_15px_rgba(6,182,212,0.2)]">
                    <div className="scanline-overlay opacity-20" />
                    <h2 className="text-xl text-yellow-400 font-title border-b border-cyan-800 pb-2 mb-4">STATUS</h2>

                    <div className="mb-6 space-y-2">
                        <div className="flex justify-between"><span className="text-cyan-500">NAME:</span> <span>{gameState.stats?.name}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">CLASS:</span> <span>{gameState.stats?.charClass.name}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">CREDITS:</span> <span className="text-yellow-300">{gameState.credits}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">HEALTH:</span> <span className={`${gameState.stats?.currentHp! < 10 ? 'text-red-500 animate-pulse' : 'text-green-400'}`}>{gameState.stats?.currentHp} / {gameState.stats?.maxHp}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">TIME:</span> <span>{isNight ? "Night Cycle" : "Day Cycle"}</span></div>
                    </div>

                    <h3 className="text-lg text-cyan-300 font-display border-b border-cyan-800 pb-1 mb-2">INVENTORY</h3>
                    <ul className="text-xs space-y-1 mb-6 font-mono text-gray-300">
                        {gameState.inventory.length === 0 && <li>Empty</li>}
                        {gameState.inventory.map((item, idx) => (
                            <li key={idx} className="flex justify-between">
                                <span>{item.name}</span>
                                {item.count > 1 && <span className="text-gray-500">x{item.count}</span>}
                            </li>
                        ))}
                    </ul>

                    <h3 className="text-lg text-cyan-300 font-display border-b border-cyan-800 pb-1 mb-2">ACTIVE QUESTS</h3>
                    <ul className="text-xs space-y-2 font-mono">
                        {gameState.quests.filter(q => q.status === 'active').length === 0 && <li className="text-gray-500">No active quests.</li>}
                        {gameState.quests.filter(q => q.status === 'active').map(q => (
                            <li key={q.id}>
                                <div className="text-yellow-200 mb-1">{q.title}</div>
                                <div className="text-gray-400 pl-2 border-l-2 border-gray-700">{q.steps[q.currentStepIndex].description}</div>
                            </li>
                        ))}
                    </ul>
                </div>
            </div>

            {/* CENTER COLUMN - VIEWPORT */}
            <div className="w-full md:w-2/4 flex flex-col gap-4 order-1 md:order-2 h-1/2 md:h-full">
                {/* Visual */}
                <div className="relative h-1/2 md:h-3/5 bg-black border-2 border-cyan-800 rounded overflow-hidden shadow-[0_0_20px_rgba(0,0,0,0.8)] group">
                    <img src={locImg} alt={locName} className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-gray-900 via-transparent to-transparent" />
                    <div className="scanline-overlay opacity-30" />

                    {/* Location Title Overlay */}
                    <div className="absolute bottom-4 left-4 right-4">
                        <h1 className="text-2xl md:text-3xl font-title text-transparent bg-clip-text bg-gradient-to-r from-cyan-300 to-blue-500 drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)]">{locName}</h1>
                    </div>

                    {/* NPC Overlays */}
                    <div className="absolute bottom-0 right-4 flex gap-4">
                        {locNpcs.filter(id => !gameState.defeatedNpcs?.includes(id)).map(npcId => {
                            const npc = NPC_DATABASE[npcId];
                            if(!npc) return null;
                            return (
                                <img 
                                    key={npcId} 
                                    src={npc.imageUrl} 
                                    className={`w-24 h-24 object-cover object-top border-2 border-transparent hover:border-yellow-400 rounded-t-lg transition-transform cursor-pointer hover:scale-105 ${currentNpcId === npcId ? 'border-yellow-400 scale-105 bg-black/50' : ''}`}
                                    onClick={() => startDialogue(npcId)}
                                    title={npc.name}
                                />
                            );
                        })}
                    </div>
                </div>

                {/* Log & Dialogue */}
                <div className="flex-1 bg-black/90 border border-gray-700 p-4 rounded font-mono text-sm md:text-base overflow-y-auto relative no-scrollbar" ref={scrollRef}>
                    {dialogueNode ? (
                        <div className="animate-fade-in">
                            <div className="text-yellow-400 mb-2 font-bold">{NPC_DATABASE[currentNpcId!].name}:</div>
                            <div className="text-white mb-6 p-3 bg-gray-800/50 rounded border-l-2 border-yellow-500">"{dialogueNode.text}"</div>
                            <div className="flex flex-col gap-2">
                                {dialogueNode.options.map((opt, idx) => {
                                    // Check requirements
                                    if (opt.reqSkill && gameState.stats && (gameState.stats.stats[opt.reqSkill] || 0) < (opt.reqVal || 0)) return null;
                                    if (opt.reqItem && !gameState.inventory.find(i => i.id === opt.reqItem)) return null;
                                    if (opt.reqQuestState) {
                                        const q = gameState.quests.find(q => q.id === opt.reqQuestState!.id);
                                        if(!q) return null;
                                        if (q.currentStepIndex !== opt.reqQuestState.step) return null; 
                                        // Simple exact step match for now
                                    }
                                    if (opt.reqTime && ((opt.reqTime === 'day' && isNight) || (opt.reqTime === 'night' && !isNight))) return null;

                                    return (
                                        <button 
                                            key={idx}
                                            onClick={() => handleDialogueOption(opt)}
                                            className="text-left text-cyan-400 hover:text-cyan-200 hover:bg-cyan-900/30 p-2 rounded transition-colors border border-transparent hover:border-cyan-700"
                                        >
                                            {idx + 1}. {opt.label}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-1 pb-4">
                            {gameState.history.map((line, i) => (
                                <div key={i} className={`break-words leading-relaxed ${line.startsWith('>') ? 'text-gray-400 italic' : line.startsWith('[COMBAT]') ? 'text-red-400' : 'text-gray-300'}`}>
                                    {i === gameState.history.length - 1 ? <Typewriter text={line} textKey={logKey} /> : line}
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            {/* RIGHT COLUMN - COMMANDS */}
            <div className="w-full md:w-1/4 flex flex-col gap-4 order-3 h-1/4 md:h-full overflow-hidden">
                <div className="bg-gray-900/80 border border-cyan-700 p-4 rounded h-full overflow-y-auto no-scrollbar shadow-[0_0_15px_rgba(6,182,212,0.2)]">
                    <div className="scanline-overlay opacity-20" />

                    {/* Navigation */}
                    <div className="mb-6">
                        <h3 className="text-cyan-500 font-display text-xs tracking-widest mb-3 border-b border-gray-700 pb-1">NAVIGATION</h3>
                        <div className="grid grid-cols-1 gap-2">
                            {locExits.map(exitId => {
                                const loc = locations[exitId];
                                if (!loc) return null;
                                return (
                                    <CommandButton 
                                        key={exitId} 
                                        label={`Go to ${loc.name}`} 
                                        onClick={() => handleMove(exitId)} 
                                        className="w-full text-left justify-start pl-4"
                                    />
                                );
                            })}
                        </div>
                    </div>

                    {/* Interactions */}
                    <div className="mb-6">
                        <h3 className="text-cyan-500 font-display text-xs tracking-widest mb-3 border-b border-gray-700 pb-1">INTERACTIONS</h3>
                        <div className="flex flex-col gap-2">
                            {/* General Actions */}
                            {locActions.map(action => (
                                <CommandButton key={action} label={action} onClick={() => handleAction(action)} />
                            ))}

                            {/* Searchables */}
                            {locSearchables.filter(s => {
                                // Hide if completed one-time searchables (simplified logic)
                                if (gameState.lootedContainers.includes(s.id) && !s.locked) return false;
                                return true;
                            }).map(s => (
                                <CommandButton 
                                    key={s.id} 
                                    label={`${s.locked && !gameState.unlockedContainers.includes(s.id) ? '🔒 ' : ''}${s.label}`} 
                                    onClick={() => handleSearch(s.id)} 
                                    className={`${s.locked && !gameState.unlockedContainers.includes(s.id) ? 'text-red-400 border-red-900/50 hover:bg-red-900/20' : ''}`}
                                />
                            ))}
                        </div>
                    </div>

                    {/* System */}
                    <div className="mt-auto pt-4 border-t border-gray-700 flex gap-2 justify-center">
                        <button onClick={onSave} className="text-xs text-gray-500 hover:text-white transition-colors">SAVE DATA</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { StartScreen, OpeningCrawl, CharacterCreator } from './components/Cinematics';
import { Dashboard } from './components/Dashboard';
import { BackgroundAudioPlayer, FullscreenButton } from './components/Shared';
import { loadGame, saveGame } from './utils';
import { initialLocations, initialQuests, AUDIO } from './data';
import { SaveData, Character, Item, Quest } from './types';

// Default State for new games
const DEFAULT_GAME_STATE: SaveData = {
    currentLocationId: 'spaceport',
    stats: null,
    inventory: [{ id: '1', name: 'Blaster Pistol', rarity: 'rare', count: 1, type: 'weapon', dmg: 8 }],
    quests: initialQuests,
    credits: 100,
    isNight: false,
    visitedLocations: ['spaceport'],
    lootedContainers: [],
    unlockedContainers: [],
    history: ["System Initialized.", "Location: Tatooine, Outer Rim.", "Objective: Survive."],
    defeatedNpcs: []
};

const App = () => {
    const [screen, setScreen] = useState<'START' | 'INTRO' | 'CREATOR' | 'GAME'>('START');
    const [gameState, setGameState] = useState<SaveData>(DEFAULT_GAME_STATE);
    const [hasSave, setHasSave] = useState(false);

    // Audio Logic
    const [audioTrack, setAudioTrack] = useState(AUDIO.MENU_THEME);
    const [audioVolume, setAudioVolume] = useState(0.5);

    useEffect(() => {
        const saved = loadGame();
        if (saved) {
            setHasSave(true);
        }
    }, []);

    // Manage Audio based on Screen and Location
    useEffect(() => {
        if (screen === 'START' || screen === 'CREATOR') {
            setAudioTrack(AUDIO.MENU_THEME);
            setAudioVolume(0.4);
        } else if (screen === 'INTRO') {
            setAudioTrack(AUDIO.MAIN_TITLE);
            setAudioVolume(0.6);
        } else if (screen === 'GAME') {
            const locId = gameState.currentLocationId;
            if (locId === 'mos_eisley_cantina') {
                setAudioTrack(AUDIO.CANTINA_THEME_1);
                setAudioVolume(0.3);
            } else {
                setAudioTrack(AUDIO.AMBIENT_THEME);
                setAudioVolume(0.2);
            }
        }
    }, [screen, gameState.currentLocationId]);

    const handleNewGame = () => {
        setGameState(DEFAULT_GAME_STATE);
        setScreen('INTRO');
    };

    const handleContinue = () => {
        const saved = loadGame();
        if (saved) {
            setGameState(saved);
            setScreen('GAME');
        }
    };

    const handleIntroFinish = () => {
        setScreen('CREATOR');
    };

    const handleCharacterCreated = (char: Character) => {
        setGameState(prev => ({
            ...prev,
            stats: char,
            // Merge starting class item into inventory
            inventory: [...prev.inventory, char.charClass.startingItem]
        }));
        setScreen('GAME');
    };

    const handleSave = () => {
        saveGame(gameState);
        setGameState(prev => ({ ...prev, history: [...prev.history, "Game Saved."] }));
    };

    return (
        <div className="w-full h-full relative font-sans select-none">
            <FullscreenButton />
            <BackgroundAudioPlayer src={audioTrack} volume={audioVolume} isPlaying={true} loop={true} />

            {screen === 'START' && (
                <StartScreen 
                    onNewGame={handleNewGame} 
                    onContinue={handleContinue} 
                    hasSave={hasSave} 
                />
            )}

            {screen === 'INTRO' && (
                <OpeningCrawl 
                    onFinished={handleIntroFinish} 
                    volume={0.6} 
                />
            )}

            {screen === 'CREATOR' && (
                <CharacterCreator 
                    onFinished={handleCharacterCreated} 
                />
            )}

            {screen === 'GAME' && (
                <div className="w-full h-full bg-gray-900 overflow-hidden relative animate-fade-in">
                    <Dashboard 
                        gameState={gameState} 
                        setGameState={setGameState} 
                        locations={initialLocations}
                        onSave={handleSave}
                    />
                </div>
            )}
        </div>
    );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { StartScreen, OpeningCrawl, CharacterCreator } from './components/Cinematics';
import { Dashboard } from './components/Dashboard';
import { BackgroundAudioPlayer, FullscreenButton } from './components/Shared';
import { loadGame, saveGame } from './utils';
import { initialLocations, initialQuests, AUDIO } from './data';
import { SaveData, Character, Item, Quest } from './types';

// Default State for new games
const DEFAULT_GAME_STATE: SaveData = {
    currentLocationId: 'spaceport',
    stats: null,
    inventory: [{ id: '1', name: 'Blaster Pistol', rarity: 'rare', count: 1, type: 'weapon', dmg: 8 }],
    quests: initialQuests,
    credits: 100,
    isNight: false,
    visitedLocations: ['spaceport'],
    lootedContainers: [],
    unlockedContainers: [],
    history: ["System Initialized.", "Location: Tatooine, Outer Rim.", "Objective: Survive."],
    defeatedNpcs: []
};

const App = () => {
    const [screen, setScreen] = useState<'START' | 'INTRO' | 'CREATOR' | 'GAME'>('START');
    const [gameState, setGameState] = useState<SaveData>(DEFAULT_GAME_STATE);
    const [hasSave, setHasSave] = useState(false);

    // Audio Logic
    const [audioTrack, setAudioTrack] = useState(AUDIO.MENU_THEME);
    const [audioVolume, setAudioVolume] = useState(0.5);
    const [isGlobalAudioPlaying, setIsGlobalAudioPlaying] = useState(true);

    useEffect(() => {
        const saved = loadGame();
        if (saved) {
            setHasSave(true);
        }
    }, []);

    // Manage Audio based on Screen and Location
    useEffect(() => {
        if (screen === 'START') {
            setAudioTrack(AUDIO.MENU_THEME);
            setAudioVolume(0.4);
            setIsGlobalAudioPlaying(true);
        } else if (screen === 'INTRO') {
            // OpeningCrawl handles its own audio (Main Title with delay)
            setIsGlobalAudioPlaying(false);
        } else if (screen === 'CREATOR') {
            // CharacterCreator handles its own audio (Menu theme with fade in)
            setIsGlobalAudioPlaying(false);
        } else if (screen === 'GAME') {
            setIsGlobalAudioPlaying(true);
            const locId = gameState.currentLocationId;
            if (locId === 'mos_eisley_cantina') {
                setAudioTrack(AUDIO.CANTINA_THEME_1);
                setAudioVolume(0.3);
            } else {
                setAudioTrack(AUDIO.AMBIENT_THEME);
                setAudioVolume(0.2);
            }
        }
    }, [screen, gameState.currentLocationId]);

    const handleNewGame = () => {
        setGameState(DEFAULT_GAME_STATE);
        setScreen('INTRO');
    };

    const handleContinue = () => {
        const saved = loadGame();
        if (saved) {
            setGameState(saved);
            setScreen('GAME');
        }
    };

    const handleIntroFinish = () => {
        setScreen('CREATOR');
    };

    const handleCharacterCreated = (char: Character) => {
        setGameState(prev => ({
            ...prev,
            stats: char,
            // Merge starting class item into inventory
            inventory: [...prev.inventory, char.charClass.startingItem]
        }));
        setScreen('GAME');
    };

    const handleSave = () => {
        saveGame(gameState);
        setGameState(prev => ({ ...prev, history: [...prev.history, "Game Saved."] }));
    };

    return (
        <div className="w-full h-full relative font-sans select-none">
            <FullscreenButton />
            <BackgroundAudioPlayer src={audioTrack} volume={audioVolume} isPlaying={isGlobalAudioPlaying} loop={true} />

            {screen === 'START' && (
                <StartScreen 
                    onNewGame={handleNewGame} 
                    onContinue={handleContinue} 
                    hasSave={hasSave} 
                />
            )}

            {screen === 'INTRO' && (
                <OpeningCrawl 
                    onFinished={handleIntroFinish} 
                    volume={0.6} 
                />
            )}

            {screen === 'CREATOR' && (
                <CharacterCreator 
                    onFinished={handleCharacterCreated} 
                />
            )}

            {screen === 'GAME' && (
                <div className="w-full h-full bg-gray-900 overflow-hidden relative animate-fade-in">
                    <Dashboard 
                        gameState={gameState} 
                        setGameState={setGameState} 
                        locations={initialLocations}
                        onSave={handleSave}
                    />
                </div>
            )}
        </div>
    );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

export interface Searchable { 
    id: string; 
    label: string; 
    description: string; 
    item?: string; 
    credits?: number; 
    chance: number;
    reqQuestState?: { id: string, step: number, completed?: boolean };
    questUpdate?: { id: string, step: number };
    locked?: boolean;
    difficulty?: 'easy' | 'medium' | 'hard';
}

export interface Encounter { 
    id: string; 
    description: string; 
    lootLabel?: string; 
    lootDescription?: string; 
    item?: string; 
    credits?: number; 
    chance: number; 
    onlyNight?: boolean; 
    onlyDay?: boolean; 
}

export interface Location { 
    id: string; 
    name: string; 
    description: string; 
    detailedDescription?: string; 
    firstVisitDescription?: string; 
    imageUrl: string; 
    exits: string[]; 
    actions?: string[]; 
    npcs?: string[]; 
    searchables?: Searchable[]; 
    encounters?: Encounter[]; 
    nightName?: string; 
    nightDescription?: string; 
    nightDetailedDescription?: string; 
    nightImageUrl?: string; 
    nightExits?: string[]; 
    nightActions?: string[]; 
    nightNpcs?: string[]; 
    nightSearchables?: Searchable[]; 
    ambient?: string[]; 
}

export interface Locations { [key: string]: Location; }

export interface Stats { str: number; per: number; end: number; cha: number; int: number; agi: number; lck: number; }

export interface Item { 
    id: string; 
    name: string; 
    rarity: 'common' | 'uncommon' | 'rare' | 'legendary'; 
    count: number; 
    type?: 'weapon' | 'consumable' | 'misc'; 
    dmg?: number; 
    heal?: number; 
}

export interface QuestStep { id: number; description: string; completed: boolean; }

export interface Quest { 
    id: string; 
    title: string; 
    description: string; 
    status: 'locked' | 'active' | 'completed'; 
    currentStepIndex: number; 
    steps: QuestStep[]; 
    reward?: string; 
    type: 'main' | 'side'; 
}

export interface Race { id: string; name: string; description: string; bonuses: Partial<Stats>; }

export interface CharClass { id: string; name: string; description: string; bonuses: Partial<Stats>; startingItem: Item; }

export interface Character { 
    name: string; 
    race: Race; 
    charClass: CharClass; 
    stats: Stats; 
    currentHp: number; 
    maxHp: number; 
    background: string; 
    party: string[]; 
}

export interface Enemy { id: string; name: string; hp: number; maxHp: number; dmg: number; xp: number; credits: number; imageUrl: string; introText: string; }

export interface CombatState { active: boolean; enemy: Enemy | null; log: string[]; turn: 'player' | 'enemy'; }

export interface DialogueOption { 
    label: string; 
    nextId: string | null; 
    reqSkill?: keyof Stats; 
    reqVal?: number; 
    reqItem?: string; 
    reqQuestState?: { id: string, step: number, completed?: boolean }; 
    reqTime?: 'day' | 'night'; 
    action?: (gameState: any) => void; 
}

export interface DialogueNode { id: string; text: string; options: DialogueOption[]; }

export interface NPC { id: string; name: string; imageUrl: string; greetingId: string; nightGreetingId?: string; dialogueTree: Record<string, DialogueNode>; }

export interface HoloNetArticle { id: string; headline: string; body: string; source: string; date: string; }

// --- PODRACING TYPES ---
export interface Podracer {
    id: string;
    name: string;
    color: string;
    odds: number; // e.g. 2.5 means 2.5x payout
    speedMod: number; // Internal speed variance
}

export interface ActiveRace {
    type: 'rookie' | 'main';
    startTime: number; // Timestamp
    betDriverId: string | null;
    betAmount: number;
    completed: boolean;
}

export interface SaveData { 
    currentLocationId: string; 
    stats: Character | null; 
    inventory: Item[]; 
    quests: Quest[]; 
    credits: number; 
    isNight: boolean; 
    visitedLocations: string[]; 
    lootedContainers: string[]; 
    unlockedContainers: string[]; 
    history: string[]; 
    lastLoginDate?: string; 
    dailyStipendClaimed?: boolean; 
    defeatedNpcs?: string[]; 
    activeRace?: ActiveRace | null;
}

