import React, { useState, useEffect, useRef } from 'react';
import { DRIVERS } from '../data';
import { ActiveRace, SaveData } from '../types';
import { CommandButton } from './Shared';

interface PodracingProps {
    gameState: SaveData;
    onBetPlaced: (driverId: string, amount: number, isMainEvent: boolean) => void;
    onRaceFinished: (winnerId: string, payouts: number) => void;
    onClose: () => void;
    mode: 'betting' | 'tracker';
}

export const Podracing: React.FC<PodracingProps> = ({ gameState, onBetPlaced, onRaceFinished, onClose, mode }) => {
    // --- BETTING LOGIC ---
    const [selectedDriver, setSelectedDriver] = useState<string | null>(null);
    const [betAmount, setBetAmount] = useState(100);
    const [betMsg, setBetMsg] = useState("");

    const now = new Date();
    const day = now.getDay(); // 0=Sun, 1=Mon, ..., 6=Sat

    // Main Event: Thurs(4), Fri(5), Sat(6). Race on Sun(0).
    const isMainEventWindow = (day >= 4 && day <= 6);
    const isRaceDay = (day === 0);

    const handlePlaceBet = (isMain: boolean) => {
        if (!selectedDriver) return;
        if (gameState.credits < betAmount) {
            setBetMsg("INSUFFICIENT FUNDS");
            return;
        }
        onBetPlaced(selectedDriver, betAmount, isMain);
        setBetMsg("BET ACCEPTED. PROCEED TO GRAND STANDS.");
    };

    if (mode === 'betting') {
        return (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md">
                <div className="w-full max-w-4xl bg-black border-4 border-orange-600 rounded-lg p-6 shadow-[0_0_50px_rgba(234,88,12,0.4)] relative overflow-hidden">
                    <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20 pointer-events-none"></div>
                    <div className="scanline-overlay opacity-10"></div>

                    <div className="flex justify-between items-center border-b-2 border-orange-600 pb-4 mb-6">
                        <h1 className="text-4xl font-title text-orange-500 tracking-widest uppercase">Boonta Eve Betting</h1>
                        <button onClick={onClose} className="text-orange-500 hover:text-white font-bold text-xl">X</button>
                    </div>

                    <div className="flex gap-6 h-[500px]">
                        {/* Driver List */}
                        <div className="w-1/3 overflow-y-auto pr-2 no-scrollbar">
                            {DRIVERS.map(d => (
                                <div 
                                    key={d.id} 
                                    onClick={() => setSelectedDriver(d.id)}
                                    className={`p-4 mb-2 border-2 cursor-pointer transition-all ${selectedDriver === d.id ? 'border-orange-400 bg-orange-900/30' : 'border-gray-800 hover:border-orange-800'}`}
                                >
                                    <div className="flex justify-between items-center">
                                        <span className="font-bold text-lg text-gray-200">{d.name}</span>
                                        <div className="w-4 h-4 rounded-full" style={{ backgroundColor: d.color }}></div>
                                    </div>
                                    <div className="text-sm text-gray-500 mt-1">Payout: <span className="text-orange-400">x{d.odds}</span></div>
                                </div>
                            ))}
                        </div>

                        {/* Betting Control */}
                        <div className="w-2/3 flex flex-col justify-between">
                            <div className="bg-gray-900/80 p-6 border border-orange-800 rounded h-full flex flex-col items-center justify-center text-center">
                                {betMsg ? (
                                    <div className="text-2xl text-green-400 font-mono animate-pulse">{betMsg}</div>
                                ) : selectedDriver ? (
                                    <>
                                        <h2 className="text-2xl text-orange-400 mb-2">Selected: {DRIVERS.find(d => d.id === selectedDriver)?.name}</h2>
                                        <div className="text-gray-400 mb-8">Odds: x{DRIVERS.find(d => d.id === selectedDriver)?.odds}</div>

                                        <div className="flex items-center gap-4 mb-8">
                                            <button onClick={() => setBetAmount(Math.max(10, betAmount - 10))} className="p-2 border border-orange-600 text-orange-600 hover:bg-orange-900">-</button>
                                            <div className="text-3xl font-mono text-white w-32">{betAmount}</div>
                                            <button onClick={() => setBetAmount(betAmount + 10)} className="p-2 border border-orange-600 text-orange-600 hover:bg-orange-900">+</button>
                                        </div>

                                        <div className="flex gap-4 w-full">
                                            <button 
                                                onClick={() => handlePlaceBet(false)}
                                                className="flex-1 py-4 bg-orange-700 hover:bg-orange-600 text-white font-display text-xl uppercase tracking-wider border border-orange-400"
                                            >
                                                Start Rookie Race
                                            </button>

                                            {isMainEventWindow && (
                                                <button 
                                                    onClick={() => handlePlaceBet(true)}
                                                    className="flex-1 py-4 bg-yellow-700 hover:bg-yellow-600 text-white font-display text-xl uppercase tracking-wider border border-yellow-400 relative overflow-hidden group"
                                                >
                                                    <span className="relative z-10">Bet Main Event (Sun)</span>
                                                    <div className="absolute inset-0 bg-yellow-500/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                                                </button>
                                            )}
                                        </div>
                                        {isMainEventWindow && <div className="mt-2 text-xs text-yellow-500">Main Event pays double odds! Qualifying Sat, Race Sun.</div>}
                                    </>
                                ) : (
                                    <div className="text-gray-500 font-display text-xl">Select a Pilot to begin</div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // --- TRACKER LOGIC ---
    // If we are here, a race exists in gameState
    return <RaceTracker gameState={gameState} onRaceFinished={onRaceFinished} onClose={onClose} />;
};

const RaceTracker: React.FC<{ gameState: SaveData, onRaceFinished: (wid: string, pay: number) => void, onClose: () => void }> = ({ gameState, onRaceFinished, onClose }) => {
    const race = gameState.activeRace!;
    const [positions, setPositions] = useState<{id: string, progress: number, lap: number}[]>([]);
    const [leaderboard, setLeaderboard] = useState<any[]>([]);
    const RACE_DURATION_MS = 30 * 60 * 1000; // 30 mins
    const LAPS = 30;

    const canvasRef = useRef<HTMLDivElement>(null);

    // Initial load and Loop
    useEffect(() => {
        let animationFrame: number;

        const updateRace = () => {
            const now = Date.now();
            const elapsed = now - race.startTime;

            if (elapsed >= RACE_DURATION_MS && !race.completed) {
                // Race Finish
                // Determine winner deterministically based on seed (startTime) + speedMod
                // Simple version: Sort by speedMod
                const winner = DRIVERS.sort((a,b) => b.speedMod - a.speedMod)[0];
                let payout = 0;
                if (race.betDriverId === winner.id) {
                    const driver = DRIVERS.find(d => d.id === winner.id)!;
                    payout = race.betAmount * driver.odds * (race.type === 'main' ? 2 : 1);
                }
                onRaceFinished(winner.id, payout);
                return;
            }

            // Calculate positions
            const newPositions = DRIVERS.map(d => {
                // Base speed is 1 lap per minute (approx)
                // 30 laps in 30 mins = 1 lap/min
                // Progress (0 to 1 per lap) = (Elapsed Minutes) * SpeedMod
                const rawLaps = (elapsed / 60000) * d.speedMod; 
                const lap = Math.floor(rawLaps);
                const progress = rawLaps % 1;
                return { id: d.id, progress, lap, totalDist: rawLaps };
            });

            setPositions(newPositions);
            setLeaderboard(newPositions.sort((a, b) => b.totalDist - a.totalDist));

            animationFrame = requestAnimationFrame(updateRace);
        };

        updateRace();
        return () => cancelAnimationFrame(animationFrame);
    }, []);

    // SVG Track Path definition (Simple Oval)
    // 0% is top center, clockwise
    const getCoordinates = (progress: number) => {
        // Parametric equation for an oval/rounded rect
        // Let's use a simple ellipse for ease
        // cx=50, cy=50, rx=40, ry=20
        const angle = (progress * 2 * Math.PI) - (Math.PI / 2); // Start top
        const x = 50 + 40 * Math.cos(angle);
        const y = 50 + 25 * Math.sin(angle);
        return { x, y };
    };

    return (
        <div className="fixed inset-0 z-40 bg-black flex flex-col">
            {/* Header */}
            <div className="bg-gray-900 border-b border-gray-700 p-4 flex justify-between items-center">
                <h2 className="text-2xl font-title text-orange-500 animate-pulse">LIVE FEED: GRAND ARENA</h2>
                <div className="flex gap-4">
                     <div className="bg-black border border-orange-500 px-4 py-1 text-orange-500 font-mono">
                         LAP: {leaderboard[0]?.lap + 1 || 1} / {LAPS}
                     </div>
                     <button onClick={onClose} className="bg-red-900/50 hover:bg-red-800 text-red-200 px-4 py-1 rounded border border-red-700">EXIT FEED</button>
                </div>
            </div>

            <div className="flex-1 flex relative">
                {/* Visualizer */}
                <div className="w-3/4 bg-black relative flex items-center justify-center" ref={canvasRef}>
                    {/* Background decoration */}
                    <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-black to-black opacity-50"></div>

                    {/* Map SVG */}
                    <svg viewBox="0 0 100 100" className="w-full h-full max-h-[80vh] drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]">
                        {/* Track Line */}
                        <ellipse cx="50" cy="50" rx="40" ry="25" fill="none" stroke="#333" strokeWidth="4" />
                        <ellipse cx="50" cy="50" rx="40" ry="25" fill="none" stroke="#f97316" strokeWidth="0.5" strokeDasharray="1 1" />

                        {/* Racers */}
                        {positions.map(p => {
                            const coords = getCoordinates(p.progress);
                            const driver = DRIVERS.find(d => d.id === p.id)!;
                            return (
                                <g key={p.id} style={{ transition: 'all 0.1s linear' }}>
                                    <circle 
                                        cx={coords.x} 
                                        cy={coords.y} 
                                        r="1.5" 
                                        fill={driver.color} 
                                        stroke="white" 
                                        strokeWidth="0.2"
                                        className="drop-shadow-md"
                                    />
                                    {/* Leader Highlight */}
                                    {leaderboard[0]?.id === p.id && (
                                        <circle cx={coords.x} cy={coords.y} r="2.5" fill="none" stroke="yellow" strokeWidth="0.2" className="animate-ping" />
                                    )}
                                </g>
                            );
                        })}
                    </svg>

                    {/* Center Info */}
                    <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-center pointer-events-none">
                        <div className="text-6xl font-bold text-gray-800 font-display opacity-20">MOS ESPA</div>
                    </div>
                </div>

                {/* Leaderboard Sidebar */}
                <div className="w-1/4 bg-gray-900 border-l border-gray-700 p-4 overflow-y-auto">
                    <h3 className="text-orange-400 font-display text-lg mb-4 border-b border-gray-700 pb-2">STANDINGS</h3>
                    <div className="flex flex-col gap-2">
                        {leaderboard.map((p, idx) => {
                            const driver = DRIVERS.find(d => d.id === p.id)!;
                            const isPlayerPick = race.betDriverId === p.id;
                            return (
                                <div key={p.id} className={`flex items-center gap-3 p-2 rounded ${idx === 0 ? 'bg-yellow-900/20 border border-yellow-700' : 'bg-gray-800'}`}>
                                    <div className="font-mono text-gray-400 w-6">#{idx + 1}</div>
                                    <div className="w-3 h-3 rounded-full" style={{ backgroundColor: driver.color }}></div>
                                    <div className="flex-1">
                                        <div className={`text-sm font-bold ${isPlayerPick ? 'text-green-400' : 'text-gray-200'}`}>
                                            {driver.name} {isPlayerPick && '(YOU)'}
                                        </div>
                                        <div className="text-xs text-gray-500">Lap {p.lap + 1} - {(p.progress * 100).toFixed(0)}%</div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Character, Quest, Item, SaveData, Locations, Location, DialogueNode } from '../types';
import { IMAGES, NPC_DATABASE, ITEM_DATABASE } from '../data';
import { Typewriter, CommandButton } from './Shared';
import { SlicingGame, SabaccGame } from './Minigames';
import { Podracing } from './Podracing';

interface DashboardProps {
    gameState: SaveData;
    setGameState: React.Dispatch<React.SetStateAction<SaveData>>;
    locations: Locations;
    onSave: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ gameState, setGameState, locations, onSave }) => {
    const [dialogueNode, setDialogueNode] = useState<DialogueNode | null>(null);
    const [currentNpcId, setCurrentNpcId] = useState<string | null>(null);
    const [activeMinigame, setActiveMinigame] = useState<'slicing' | 'sabacc' | 'podracing_bet' | 'podracing_tracker' | null>(null);
    const [slicingTarget, setSlicingTarget] = useState<string | null>(null);
    const [logKey, setLogKey] = useState(0);

    const currentLocation = locations[gameState.currentLocationId];
    const isNight = gameState.isNight;

    // Derived values based on Time of Day
    const locName = isNight ? (currentLocation.nightName || currentLocation.name) : currentLocation.name;
    const locDesc = isNight ? (currentLocation.nightDescription || currentLocation.description) : currentLocation.description;
    const locImg = isNight ? (currentLocation.nightImageUrl || currentLocation.imageUrl) : currentLocation.imageUrl;
    const locExits = isNight ? (currentLocation.nightExits || currentLocation.exits) : currentLocation.exits;
    const locNpcs = isNight ? (currentLocation.nightNpcs || currentLocation.npcs || []) : (currentLocation.npcs || []);
    const locActions = isNight ? (currentLocation.nightActions || currentLocation.actions || []) : (currentLocation.actions || []);
    const locSearchables = isNight ? (currentLocation.nightSearchables || currentLocation.searchables || []) : (currentLocation.searchables || []);
    const locAmbient = currentLocation.ambient || [];

    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [gameState.history, logKey]);

    const addToLog = (text: string) => {
        setGameState(prev => ({
            ...prev,
            history: [...prev.history, text].slice(-50) // Keep last 50 lines
        }));
        setLogKey(k => k + 1);
    };

    // --- ACTIONS ---

    const handleMove = (exitId: string) => {
        const nextLoc = locations[exitId];
        if (!nextLoc) return;

        setDialogueNode(null);
        setCurrentNpcId(null);

        setGameState(prev => {
            const visited = prev.visitedLocations.includes(exitId);
            const newHistory = [...prev.history];

            // Add description to log if first visit
            if (!visited && nextLoc.firstVisitDescription) {
                // We'll handle this log addition in the effect or just here
            }

            return {
                ...prev,
                currentLocationId: exitId,
                visitedLocations: visited ? prev.visitedLocations : [...prev.visitedLocations, exitId]
            };
        });
    };

    const handleRest = () => {
        setGameState(prev => ({
            ...prev,
            isNight: !prev.isNight,
            stats: prev.stats ? { ...prev.stats, currentHp: prev.stats.maxHp } : null
        }));
        addToLog(isNight ? "You sleep until morning. The suns rise over the dunes." : "You rest until evening. The air cools down.");
    };

    const handleAction = (action: string) => {
        if (action === 'Look Around') {
            const detailed = isNight ? (currentLocation.nightDetailedDescription || currentLocation.detailedDescription) : currentLocation.detailedDescription;
            addToLog(detailed || "You see nothing unusual.");

            // Trigger chance encounters
            if (currentLocation.encounters) {
                const roll = Math.random();
                const encounter = currentLocation.encounters.find(e => {
                    if (e.onlyNight && !isNight) return false;
                    if (e.onlyDay && isNight) return false;
                    return roll < e.chance;
                });

                if (encounter) {
                    addToLog(`> ${encounter.description}`);
                    if (encounter.lootDescription && encounter.lootLabel) {
                         // Simplify: Just give loot immediately for this demo logic
                         addToLog(`You found: ${encounter.lootDescription}`);
                         if (encounter.credits) {
                             setGameState(prev => ({ ...prev, credits: prev.credits + encounter.credits! }));
                             addToLog(`+${encounter.credits} Credits`);
                         }
                         if (encounter.item) {
                             const itemObj = ITEM_DATABASE.find(i => i.id === encounter.item);
                             if (itemObj) {
                                 setGameState(prev => ({ ...prev, inventory: [...prev.inventory, itemObj] }));
                                 addToLog(`Received: ${itemObj.name}`);
                             }
                         }
                    }
                }
            }
        } 
        else if (action === 'Play Sabacc') {
            if (gameState.credits < 10) {
                addToLog("You need at least 10 credits to play.");
                return;
            }
            setActiveMinigame('sabacc');
        }
        else if (action === 'Rest (Heal)') {
            handleRest();
        }
        else if (action === 'Collect Daily Stipend') {
             if (!gameState.dailyStipendClaimed) {
                 setGameState(prev => ({ ...prev, credits: prev.credits + 50, dailyStipendClaimed: true }));
                 addToLog("Guild Stipend Collected: 50 Credits.");
             } else {
                 addToLog("You have already collected your stipend for today.");
             }
        }
        else if (action === 'Access Betting Terminal') {
            setActiveMinigame('podracing_bet');
        }
        else if (action === 'Enter Grand Stands') {
            if (gameState.activeRace && !gameState.activeRace.completed) {
                setActiveMinigame('podracing_tracker');
            } else {
                addToLog("There is no active race at the moment. Place a bet to trigger a Rookie event.");
            }
        }
    };

    const handleSearch = (searchableId: string) => {
        const target = locSearchables.find(s => s.id === searchableId);
        if (!target) return;

        // Check if already looted/unlocked
        if (gameState.lootedContainers.includes(searchableId)) {
            addToLog("Empty.");
            return;
        }

        // Check requirements
        if (target.reqQuestState) {
            const quest = gameState.quests.find(q => q.id === target.reqQuestState!.id);
            if (!quest || quest.currentStepIndex < target.reqQuestState.step) {
                addToLog("You don't see anything of interest yet.");
                return;
            }
        }

        if (target.locked && !gameState.unlockedContainers.includes(searchableId)) {
            setSlicingTarget(searchableId);
            setActiveMinigame('slicing');
            return;
        }

        // Success
        addToLog(target.description);
        if (target.credits) {
            setGameState(prev => ({ ...prev, credits: prev.credits + target.credits! }));
            addToLog(`+${target.credits} Credits`);
        }
        if (target.item) {
            const itemObj = ITEM_DATABASE.find(i => i.id === target.item);
            if (itemObj) {
                setGameState(prev => ({ ...prev, inventory: [...prev.inventory, itemObj] }));
                addToLog(`Found: ${itemObj.name}`);
            }
        }

        // Quest Updates
        if (target.questUpdate) {
             setGameState(prev => ({
                 ...prev,
                 quests: prev.quests.map(q => q.id === target.questUpdate!.id ? { ...q, currentStepIndex: target.questUpdate!.step } : q)
             }));
             addToLog("Quest Updated.");
        }

        setGameState(prev => ({ ...prev, lootedContainers: [...prev.lootedContainers, searchableId] }));
    };

    // --- DIALOGUE ---

    const startDialogue = (npcId: string) => {
        const npc = NPC_DATABASE[npcId];
        if (!npc) return;
        setCurrentNpcId(npcId);

        // Determine greeting based on conditions (not fully impl in this demo, defaulting to 'intro')
        const greetingId = (isNight && npc.nightGreetingId) ? npc.nightGreetingId : npc.greetingId;
        setDialogueNode(npc.dialogueTree[greetingId]);
    };

    const handleDialogueOption = (opt: any) => {
        if (opt.action) {
            // Create a proxy for gameState mutations
            const gameProxy = {
                credits: gameState.credits,
                setCredits: (fn: any) => setGameState(prev => ({ ...prev, credits: fn(prev.credits) })),
                addToLog: addToLog,
                updateQuest: (qid: string, step: number) => setGameState(prev => ({ ...prev, quests: prev.quests.map(q => q.id === qid ? { ...q, currentStepIndex: step } : q) })),
                completeQuest: (qid: string) => setGameState(prev => ({ ...prev, quests: prev.quests.map(q => q.id === qid ? { ...q, status: 'completed' } : q) })),
                setInventory: (fn: any) => setGameState(prev => ({ ...prev, inventory: fn(prev.inventory) })),
                setStats: (fn: any) => setGameState(prev => ({ ...prev, stats: fn(prev.stats) })),
                setQuests: (fn: any) => setGameState(prev => ({ ...prev, quests: fn(prev.quests) })),
                setDefeatedNpcs: (fn: any) => setGameState(prev => ({ ...prev, defeatedNpcs: fn(prev.defeatedNpcs) })),
            };
            opt.action(gameProxy);
        }

        if (opt.nextId) {
            const npc = NPC_DATABASE[currentNpcId!];
            setDialogueNode(npc.dialogueTree[opt.nextId]);
        } else {
            setDialogueNode(null);
            setCurrentNpcId(null);
        }
    };

    // --- RENDER HELPERS ---

    const renderMinigame = () => {
        if (activeMinigame === 'slicing') {
            return (
                <SlicingGame 
                    difficulty="medium"
                    onClose={() => setActiveMinigame(null)}
                    onWin={() => {
                        setActiveMinigame(null);
                        setGameState(prev => ({ ...prev, unlockedContainers: [...prev.unlockedContainers, slicingTarget!] }));
                        addToLog("Access Granted. Security systems bypassed.");
                        // Auto-loot after unlock
                        handleSearch(slicingTarget!);
                    }}
                    onLose={() => {
                        setActiveMinigame(null);
                        addToLog("Slicing failed. Security lockout engaged.");
                    }}
                />
            );
        }
        if (activeMinigame === 'sabacc') {
            return (
                <SabaccGame 
                    betAmount={10}
                    onClose={() => setActiveMinigame(null)}
                    onFinish={(result, amount) => {
                        setActiveMinigame(null);
                        if (result === 'win') {
                            setGameState(prev => ({ ...prev, credits: prev.credits + amount }));
                            addToLog(`You won the hand! gained ${amount} credits.`);
                        } else if (result === 'lose') {
                            setGameState(prev => ({ ...prev, credits: prev.credits - 10 })); // Lost bet
                            addToLog("You lost the hand.");
                        } else {
                            addToLog("Draw. Credits returned.");
                        }
                    }}
                />
            );
        }
        if (activeMinigame === 'podracing_bet' || activeMinigame === 'podracing_tracker') {
            return (
                <Podracing 
                    gameState={gameState}
                    mode={activeMinigame === 'podracing_bet' ? 'betting' : 'tracker'}
                    onClose={() => setActiveMinigame(null)}
                    onBetPlaced={(driverId, amount, isMain) => {
                        setGameState(prev => ({
                            ...prev,
                            credits: prev.credits - amount,
                            activeRace: {
                                type: isMain ? 'main' : 'rookie',
                                startTime: Date.now(), // Race starts now for visual simplicity in this prototype, or schedule it
                                betDriverId: driverId,
                                betAmount: amount,
                                completed: false
                            }
                        }));
                        // The component stays open or can display a message
                    }}
                    onRaceFinished={(winnerId, payout) => {
                        setActiveMinigame(null);
                        setGameState(prev => ({
                            ...prev,
                            credits: prev.credits + payout,
                            activeRace: { ...prev.activeRace!, completed: true }
                        }));
                        if (payout > 0) {
                            addToLog(`RACE UPDATE: Your driver won! You received ${payout} credits.`);
                        } else {
                            addToLog(`RACE UPDATE: Your driver lost. Better luck next time.`);
                        }
                    }}
                />
            );
        }
        return null;
    };

    return (
        <div className="flex flex-col md:flex-row h-full w-full max-w-7xl mx-auto md:p-4 gap-4 text-cyan-100 font-sans text-sm md:text-base">
            {renderMinigame()}

