import React, { useState, useEffect, useRef } from 'react';
import { DRIVERS, AUDIO } from '../data';
import { ActiveRace, SaveData } from '../types';
import { BackgroundAudioPlayer } from './Shared';

interface PodracingProps {
    gameState: SaveData;
    onBetPlaced: (driverId: string, amount: number, isMainEvent: boolean, startTime: number) => void;
    onRaceFinished: (winnerId: string, payouts: number) => void;
    onClose: () => void;
    mode: 'betting' | 'tracker';
}

export const Podracing: React.FC<PodracingProps> = ({ gameState, onBetPlaced, onRaceFinished, onClose, mode }) => {
    // --- BETTING LOGIC ---
    const [selectedDriver, setSelectedDriver] = useState<string | null>(null);
    const [betAmount, setBetAmount] = useState(100);
    const [view, setView] = useState<'form' | 'receipt'>('form');

    const now = new Date();
    const day = now.getDay(); // 0=Sun, 1=Mon... 4=Thu, 5=Fri, 6=Sat

    // Main Event Window: Thursday (4) to Saturday (6)
    const isMainEventWindow = (day >= 4 && day <= 6);

    const handlePlaceBet = (isMain: boolean) => {
        if (!selectedDriver) return;
        if (gameState.credits < betAmount) return; // Should be handled by UI disable

        let startTime = Date.now();

        if (isMain) {
            // Schedule for next Sunday at 12:00 PM
            const nextSunday = new Date();
            const daysUntilSunday = (7 - day) % 7;
            // If today is Sunday (0), daysUntil is 0. But betting is closed Sunday.
            // If Thurs (4), daysUntil = 3. Sun is 3 days away.
            nextSunday.setDate(now.getDate() + (daysUntilSunday === 0 ? 7 : daysUntilSunday));
            nextSunday.setHours(12, 0, 0, 0);
            startTime = nextSunday.getTime();
        }

        onBetPlaced(selectedDriver, betAmount, isMain, startTime);
        setView('receipt');
    };

    if (mode === 'betting') {
        return (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-md animate-fade-in">
                <div className="w-full max-w-4xl bg-black border-4 border-orange-600 rounded-lg p-6 shadow-[0_0_50px_rgba(234,88,12,0.4)] relative overflow-hidden h-[600px] flex flex-col">
                    <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20 pointer-events-none"></div>
                    <div className="scanline-overlay opacity-10"></div>

                    {/* Header */}
