                                    className="w-full py-3 bg-orange-600 hover:bg-orange-500 text-black font-bold font-display uppercase tracking-wider rounded"
                                >
                                    Close Terminal
                                </button>
                            </div>
                        </div>
                    ) : (
                        <div className="flex gap-6 h-full z-10 overflow-hidden">
                            {/* Driver List */}
                            <div className="w-1/3 overflow-y-auto pr-2 no-scrollbar border-r border-orange-900/50">
                                {DRIVERS.map(d => (
                                    <div 
                                        key={d.id} 
