                                                    <button onClick={() => setBetAmount(Math.max(10, betAmount + 50))} className="w-12 h-12 flex items-center justify-center border border-orange-600 text-orange-600 hover:bg-orange-600 hover:text-black transition-colors rounded text-xl font-bold">+</button>
