                                            </div>

                                            <div className="grid grid-cols-2 gap-4 w-full mt-auto">
                                                <button 
                                                    onClick={() => handlePlaceBet(false)}
                                                    disabled={gameState.credits < betAmount}
                                                    className="py-4 bg-gray-800 hover:bg-orange-900 text-white font-display text-lg uppercase tracking-wider border border-gray-600 hover:border-orange-500 transition-all disabled:opacity-50 disabled:cursor-not-allowed group"
                                                >
                                                    <span className="block text-xs text-gray-500 group-hover:text-orange-300">Instant Event</span>
                                                    Start Rookie Race
                                                </button>

                                                <button 
                                                    onClick={() => handlePlaceBet(true)}
                                                    disabled={!isMainEventWindow || gameState.credits < betAmount}
                                                    className={`py-4 font-display text-lg uppercase tracking-wider border transition-all relative overflow-hidden group disabled:opacity-50 disabled:cursor-not-allowed ${isMainEventWindow ? 'bg-orange-700 hover:bg-orange-600 border-orange-500 text-white' : 'bg-gray-900 border-gray-800 text-gray-600'}`}
                                                >
                                                    <span className={`block text-xs mb-1 ${isMainEventWindow ? 'text-orange-200' : 'text-gray-700'}`}>Sunday Main Event</span>
                                                    {isMainEventWindow ? 'Place Bet (2x Payout)' : 'Betting Closed'}
                                                    {isMainEventWindow && <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>}
                                                </button>
                                            </div>
                                            {!isMainEventWindow && <div className="text-xs text-red-900 mt-2">Main Event betting only open Thu-Sat.</div>}
                                        </>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        );
    }

    // --- TRACKER LOGIC ---
    return <RaceTracker gameState={gameState} onRaceFinished={onRaceFinished} onClose={onClose} />;
};

const RaceTracker: React.FC<{ gameState: SaveData, onRaceFinished: (wid: string, pay: number) => void, onClose: () => void }> = ({ gameState, onRaceFinished, onClose }) => {
    const race = gameState.activeRace!;
    const [positions, setPositions] = useState<{id: string, progress: number, lap: number, totalDist: number}[]>([]);
    const [leaderboard, setLeaderboard] = useState<any[]>([]);
    const [timeToStart, setTimeToStart] = useState<number>(0);

    // Config
    const LAPS = 30;
    const TRACK_LENGTH_METERS = 5000; // Arbitrary unit
    const BASE_SPEED = 0.0003; // Progress per ms

    const canvasRef = useRef<HTMLDivElement>(null);

    // Countdown / Race Loop
    useEffect(() => {
        let animationFrame: number;

        const update = () => {
            const now = Date.now();
            const elapsed = now - race.startTime;

            if (elapsed < 0) {
                // Future Race
                setTimeToStart(Math.abs(elapsed));
                setPositions([]); // Clear positions
            } else {
                // Race Active or Finished
                setTimeToStart(0);

                // Check Finish
                // We use a deterministic logic so 'elapsed' dictates exact state
                // To support "Active" vs "Finished" states properly with persistence:

                // Calculate current positions based on elapsed time
                const newPositions = DRIVERS.map(d => {
                    // Distance = Time * Speed * SpeedMod
                    // 30 Laps. Let's say 1 Lap takes 60s / speedMod
                    // Progress (0-1) = (elapsed / 60000) * speedMod
                    const rawLaps = (elapsed / 60000) * d.speedMod * 1.5; // 1.5x speed for viewing pleasure
                    return {
                        id: d.id,
                        progress: rawLaps % 1,
                        lap: Math.floor(rawLaps),
                        totalDist: rawLaps
                    };
                });

                // Check if winner
                const winner = newPositions.find(p => p.lap >= LAPS);
                if (winner && !race.completed) {
                    // Race Over
                    // Find actual winner by sorting totalDist descending
                    newPositions.sort((a,b) => b.totalDist - a.totalDist);
                    const trueWinnerId = newPositions[0].id;

                    let payout = 0;
                    if (race.betDriverId === trueWinnerId) {
                        const driver = DRIVERS.find(d => d.id === trueWinnerId)!;
                        payout = race.betAmount * driver.odds * (race.type === 'main' ? 2 : 1);
                    }
                    onRaceFinished(trueWinnerId, payout);
                    return; // Stop loop
                }

                setPositions(newPositions);
                setLeaderboard([...newPositions].sort((a, b) => b.totalDist - a.totalDist));
            }

            animationFrame = requestAnimationFrame(update);
        };

        update();
        return () => cancelAnimationFrame(animationFrame);
    }, [race]);

    // Track Audio
    useEffect(() => {
        // Only play if race is active
        if (timeToStart === 0 && !race.completed) {
            // We use a separate player for sound effects if possible, but here we render a hidden player
        }
    }, [timeToStart, race.completed]);

    // Format MS to HH:MM:SS
    const formatTime = (ms: number) => {
        const s = Math.floor(ms / 1000);
        const h = Math.floor(s / 3600);
        const m = Math.floor((s % 3600) / 60);
        const sec = s % 60;
        return `${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}:${sec.toString().padStart(2,'0')}`;
    };

    // Pre-Race Screen
    if (timeToStart > 0) {
        return (
            <div className="fixed inset-0 z-50 bg-black flex flex-col items-center justify-center font-title animate-fade-in">
                <h1 className="text-4xl text-orange-600 mb-4 tracking-widest">EVENT SCHEDULED</h1>
                <div className="text-8xl text-white font-mono mb-8">{formatTime(timeToStart)}</div>
                <div className="text-gray-500 mb-8">Until the Boonta Eve Classic begins</div>
                <button onClick={onClose} className="border border-gray-600 px-6 py-2 text-gray-400 hover:text-white hover:border-white">RETURN TO LOBBY</button>
            </div>
        );
    }

    // Active Race Screen
    const getCoordinates = (progress: number) => {
        // Simple oval
        const angle = (progress * 2 * Math.PI) - (Math.PI / 2);
        const x = 50 + 40 * Math.cos(angle);
        const y = 50 + 25 * Math.sin(angle);
        return { x, y };
    };

    return (
        <div className="fixed inset-0 z-40 bg-black flex flex-col animate-fade-in">
             {/* Hidden SFX Player */}
             <BackgroundAudioPlayer src={AUDIO.PODRACE} volume={0.4} isPlaying={!race.completed} loop={true} />

            {/* Header */}
            <div className="bg-gray-900 border-b border-gray-800 p-4 flex justify-between items-center z-10">
                <div className="flex items-center gap-4">
                    <div className="w-3 h-3 bg-red-500 animate-pulse rounded-full"></div>
                    <h2 className="text-2xl font-title text-orange-500 tracking-widest">LIVE FEED // GRAND ARENA</h2>
                </div>
                <div className="flex gap-4 items-center">
                     <div className="bg-black border border-orange-900/50 px-6 py-2 text-orange-500 font-mono text-xl shadow-[0_0_10px_rgba(234,88,12,0.2)]">
                         LAP {Math.min((leaderboard[0]?.lap || 0) + 1, LAPS)} <span className="text-gray-600">/ {LAPS}</span>
                     </div>
                     <button onClick={onClose} className="bg-red-900/20 hover:bg-red-900/50 text-red-500 px-4 py-2 rounded border border-red-900/50 font-bold text-sm">EXIT FEED</button>
                </div>
            </div>

            <div className="flex-1 flex relative">
                {/* Visualizer */}
                <div className="w-3/4 bg-black relative flex items-center justify-center overflow-hidden" ref={canvasRef}>
                    {/* Background decoration */}
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-900 via-black to-black"></div>
                    <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/diagmonds-light.png')] opacity-10"></div>

                    {/* Map SVG */}
                    <svg viewBox="0 0 100 100" className="w-full h-full max-h-[85vh] drop-shadow-[0_0_30px_rgba(255,165,0,0.1)]">
                        {/* Track Line */}
                        <ellipse cx="50" cy="50" rx="42" ry="27" fill="none" stroke="#222" strokeWidth="6" />
                        <ellipse cx="50" cy="50" rx="42" ry="27" fill="none" stroke="#f97316" strokeWidth="0.5" strokeDasharray="0.5 2" strokeOpacity="0.5" />

                        {/* Racers */}
                        {positions.map(p => {
                            const coords = getCoordinates(p.progress);
                            const driver = DRIVERS.find(d => d.id === p.id)!;
                            const isLeader = leaderboard[0]?.id === p.id;
                            const isPlayerPick = race.betDriverId === p.id;
                            return (
                                <g key={p.id} style={{ transition: 'all 0.1s linear' }}>
                                    {/* Trail */}
                                    {isPlayerPick && <circle cx={coords.x} cy={coords.y} r="4" fill={driver.color} opacity="0.2" className="animate-ping" />}

                                    <circle 
                                        cx={coords.x} 
                                        cy={coords.y} 
                                        r={isPlayerPick ? "2" : "1.5"} 
                                        fill={driver.color} 
                                        stroke="white" 
                                        strokeWidth="0.3"
                                        className="drop-shadow-md"
                                    />
                                    {isLeader && <text x={coords.x + 3} y={coords.y} fontSize="2" fill="yellow" opacity="0.7">1st</text>}
                                </g>
                            );
                        })}
                    </svg>

                    {/* Center Info */}
                    <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-center pointer-events-none">
                        <div className="text-8xl font-bold text-gray-800 font-display opacity-10 tracking-[1em]">MOS ESPA</div>
                    </div>
                </div>

                {/* Leaderboard Sidebar */}
                <div className="w-1/4 bg-gray-900 border-l border-gray-800 p-0 flex flex-col">
                    <div className="p-4 bg-gray-950 border-b border-gray-800">
                        <h3 className="text-orange-500 font-display text-sm tracking-widest">LEADERBOARD</h3>
                    </div>
                    <div className="flex-1 overflow-y-auto no-scrollbar p-2 space-y-1">
                        {leaderboard.map((p, idx) => {
                            const driver = DRIVERS.find(d => d.id === p.id)!;
                            const isPlayerPick = race.betDriverId === p.id;
                            return (
                                <div key={p.id} className={`flex items-center gap-3 p-3 rounded transition-all ${idx === 0 ? 'bg-gradient-to-r from-yellow-900/40 to-transparent border-l-2 border-yellow-500' : 'bg-gray-800/50 border-l-2 border-transparent'}`}>
                                    <div className={`font-mono w-6 text-right ${idx===0 ? 'text-yellow-400' : 'text-gray-500'}`}>{idx + 1}</div>
                                    <div className="w-2 h-8 rounded-full" style={{ backgroundColor: driver.color }}></div>
                                    <div className="flex-1 min-w-0">
                                        <div className={`text-sm font-bold truncate ${isPlayerPick ? 'text-orange-400' : 'text-gray-300'}`}>
                                            {driver.name} {isPlayerPick && '◄'}
                                        </div>
                                        <div className="text-xs text-gray-600 font-mono">
                                            {(p.totalDist).toFixed(2)}km / {((p.totalDist / (LAPS)) * 100).toFixed(0)}%
                                        </div>
                                    </div>
                                    {isPlayerPick && <div className="text-xs bg-orange-900/80 text-orange-200 px-2 py-1 rounded">BET</div>}
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Character, Quest, Item, SaveData, Locations, Location, DialogueNode } from '../types';
import { IMAGES, NPC_DATABASE, ITEM_DATABASE } from '../data';
import { Typewriter, CommandButton } from './Shared';
import { SlicingGame, SabaccGame } from './Minigames';
import { Podracing } from './Podracing';

interface DashboardProps {
    gameState: SaveData;
    setGameState: React.Dispatch<React.SetStateAction<SaveData>>;
    locations: Locations;
    onSave: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ gameState, setGameState, locations, onSave }) => {
    const [dialogueNode, setDialogueNode] = useState<DialogueNode | null>(null);
    const [currentNpcId, setCurrentNpcId] = useState<string | null>(null);
    const [activeMinigame, setActiveMinigame] = useState<'slicing' | 'sabacc' | 'podracing_bet' | 'podracing_tracker' | null>(null);
    const [slicingTarget, setSlicingTarget] = useState<string | null>(null);
    const [logKey, setLogKey] = useState(0);

    const currentLocation = locations[gameState.currentLocationId];
    const isNight = gameState.isNight;

    // Derived values based on Time of Day
    const locName = isNight ? (currentLocation.nightName || currentLocation.name) : currentLocation.name;
    const locDesc = isNight ? (currentLocation.nightDescription || currentLocation.description) : currentLocation.description;
    const locImg = isNight ? (currentLocation.nightImageUrl || currentLocation.imageUrl) : currentLocation.imageUrl;
    const locExits = isNight ? (currentLocation.nightExits || currentLocation.exits) : currentLocation.exits;
    const locNpcs = isNight ? (currentLocation.nightNpcs || currentLocation.npcs || []) : (currentLocation.npcs || []);
    const locActions = isNight ? (currentLocation.nightActions || currentLocation.actions || []) : (currentLocation.actions || []);
    const locSearchables = isNight ? (currentLocation.nightSearchables || currentLocation.searchables || []) : (currentLocation.searchables || []);
    const locAmbient = currentLocation.ambient || [];

    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [gameState.history, logKey]);

    const addToLog = (text: string) => {
        setGameState(prev => ({
            ...prev,
            history: [...prev.history, text].slice(-50) // Keep last 50 lines
        }));
        setLogKey(k => k + 1);
    };

    // --- ACTIONS ---

    const handleMove = (exitId: string) => {
        const nextLoc = locations[exitId];
        if (!nextLoc) return;

        setDialogueNode(null);
        setCurrentNpcId(null);

        setGameState(prev => {
            const visited = prev.visitedLocations.includes(exitId);
            const newHistory = [...prev.history];
            return {
                ...prev,
                currentLocationId: exitId,
                visitedLocations: visited ? prev.visitedLocations : [...prev.visitedLocations, exitId]
            };
        });
    };

    const handleRest = () => {
        setGameState(prev => ({
            ...prev,
            isNight: !prev.isNight,
            stats: prev.stats ? { ...prev.stats, currentHp: prev.stats.maxHp } : null
        }));
        addToLog(isNight ? "You sleep until morning. The suns rise over the dunes." : "You rest until evening. The air cools down.");
    };

    const handleAction = (action: string) => {
        if (action === 'Look Around') {
            const detailed = isNight ? (currentLocation.nightDetailedDescription || currentLocation.detailedDescription) : currentLocation.detailedDescription;
            addToLog(detailed || "You see nothing unusual.");

            // Trigger chance encounters
            if (currentLocation.encounters) {
                const roll = Math.random();
                const encounter = currentLocation.encounters.find(e => {
                    if (e.onlyNight && !isNight) return false;
                    if (e.onlyDay && isNight) return false;
                    return roll < e.chance;
                });

                if (encounter) {
                    addToLog(`> ${encounter.description}`);
                    if (encounter.lootDescription && encounter.lootLabel) {
                         // Simplify: Just give loot immediately for this demo logic
                         addToLog(`You found: ${encounter.lootDescription}`);
                         if (encounter.credits) {
                             setGameState(prev => ({ ...prev, credits: prev.credits + encounter.credits! }));
                             addToLog(`+${encounter.credits} Credits`);
                         }
                         if (encounter.item) {
                             const itemObj = ITEM_DATABASE.find(i => i.id === encounter.item);
                             if (itemObj) {
                                 setGameState(prev => ({ ...prev, inventory: [...prev.inventory, itemObj] }));
                                 addToLog(`Received: ${itemObj.name}`);
                             }
                         }
                    }
                }
            }
        } 
        else if (action === 'Play Sabacc') {
            if (gameState.credits < 10) {
                addToLog("You need at least 10 credits to play.");
                return;
            }
            setActiveMinigame('sabacc');
        }
        else if (action === 'Rest (Heal)') {
            handleRest();
        }
        else if (action === 'Collect Daily Stipend') {
             if (!gameState.dailyStipendClaimed) {
                 setGameState(prev => ({ ...prev, credits: prev.credits + 50, dailyStipendClaimed: true }));
                 addToLog("Guild Stipend Collected: 50 Credits.");
             } else {
                 addToLog("You have already collected your stipend for today.");
             }
        }
        else if (action === 'Access Betting Terminal') {
            setActiveMinigame('podracing_bet');
        }
        else if (action === 'Enter Grand Stands') {
            if (gameState.activeRace && !gameState.activeRace.completed) {
                setActiveMinigame('podracing_tracker');
            } else if (gameState.activeRace && gameState.activeRace.completed) {
                addToLog("The previous race has finished. Place a new bet to watch another.");
            } else {
                addToLog("There is no active race at the moment. Place a bet at the terminal to trigger a Rookie event.");
            }
        }
    };

    const handleSearch = (searchableId: string) => {
        const target = locSearchables.find(s => s.id === searchableId);
        if (!target) return;

        // Check if already looted/unlocked
        if (gameState.lootedContainers.includes(searchableId)) {
            addToLog("Empty.");
            return;
        }

        // Check requirements
        if (target.reqQuestState) {
            const quest = gameState.quests.find(q => q.id === target.reqQuestState!.id);
            if (!quest || quest.currentStepIndex < target.reqQuestState.step) {
                addToLog("You don't see anything of interest yet.");
                return;
            }
        }

        if (target.locked && !gameState.unlockedContainers.includes(searchableId)) {
            setSlicingTarget(searchableId);
            setActiveMinigame('slicing');
            return;
        }

        // Success
        addToLog(target.description);
        if (target.credits) {
            setGameState(prev => ({ ...prev, credits: prev.credits + target.credits! }));
            addToLog(`+${target.credits} Credits`);
        }
        if (target.item) {
            const itemObj = ITEM_DATABASE.find(i => i.id === target.item);
            if (itemObj) {
                setGameState(prev => ({ ...prev, inventory: [...prev.inventory, itemObj] }));
                addToLog(`Found: ${itemObj.name}`);
            }
        }

        // Quest Updates
        if (target.questUpdate) {
             setGameState(prev => ({
                 ...prev,
                 quests: prev.quests.map(q => q.id === target.questUpdate!.id ? { ...q, currentStepIndex: target.questUpdate!.step } : q)
             }));
             addToLog("Quest Updated.");
        }

        setGameState(prev => ({ ...prev, lootedContainers: [...prev.lootedContainers, searchableId] }));
    };

    // --- DIALOGUE ---

    const startDialogue = (npcId: string) => {
        const npc = NPC_DATABASE[npcId];
        if (!npc) return;
        setCurrentNpcId(npcId);

        // Determine greeting based on conditions (not fully impl in this demo, defaulting to 'intro')
        const greetingId = (isNight && npc.nightGreetingId) ? npc.nightGreetingId : npc.greetingId;
        setDialogueNode(npc.dialogueTree[greetingId]);
    };

    const handleDialogueOption = (opt: any) => {
        if (opt.action) {
            // Create a proxy for gameState mutations
            const gameProxy = {
                credits: gameState.credits,
                setCredits: (fn: any) => setGameState(prev => ({ ...prev, credits: fn(prev.credits) })),
                addToLog: addToLog,
                updateQuest: (qid: string, step: number) => setGameState(prev => ({ ...prev, quests: prev.quests.map(q => q.id === qid ? { ...q, currentStepIndex: step } : q) })),
                completeQuest: (qid: string) => setGameState(prev => ({ ...prev, quests: prev.quests.map(q => q.id === qid ? { ...q, status: 'completed' } : q) })),
                setInventory: (fn: any) => setGameState(prev => ({ ...prev, inventory: fn(prev.inventory) })),
                setStats: (fn: any) => setGameState(prev => ({ ...prev, stats: fn(prev.stats) })),
                setQuests: (fn: any) => setGameState(prev => ({ ...prev, quests: fn(prev.quests) })),
                setDefeatedNpcs: (fn: any) => setGameState(prev => ({ ...prev, defeatedNpcs: fn(prev.defeatedNpcs) })),
            };
            opt.action(gameProxy);
        }

        if (opt.nextId) {
            const npc = NPC_DATABASE[currentNpcId!];
            setDialogueNode(npc.dialogueTree[opt.nextId]);
        } else {
            setDialogueNode(null);
            setCurrentNpcId(null);
        }
    };

    // --- RENDER HELPERS ---

    const renderMinigame = () => {
        if (activeMinigame === 'slicing') {
            return (
                <SlicingGame 
                    difficulty="medium"
                    onClose={() => setActiveMinigame(null)}
                    onWin={() => {
                        setActiveMinigame(null);
                        setGameState(prev => ({ ...prev, unlockedContainers: [...prev.unlockedContainers, slicingTarget!] }));
                        addToLog("Access Granted. Security systems bypassed.");
                        // Auto-loot after unlock
                        handleSearch(slicingTarget!);
                    }}
                    onLose={() => {
                        setActiveMinigame(null);
                        addToLog("Slicing failed. Security lockout engaged.");
                    }}
                />
            );
        }
        if (activeMinigame === 'sabacc') {
            return (
                <SabaccGame 
                    betAmount={10}
                    onClose={() => setActiveMinigame(null)}
                    onFinish={(result, amount) => {
                        setActiveMinigame(null);
                        if (result === 'win') {
                            setGameState(prev => ({ ...prev, credits: prev.credits + amount }));
                            addToLog(`You won the hand! gained ${amount} credits.`);
                        } else if (result === 'lose') {
                            setGameState(prev => ({ ...prev, credits: prev.credits - 10 })); // Lost bet
                            addToLog("You lost the hand.");
                        } else {
                            addToLog("Draw. Credits returned.");
                        }
                    }}
                />
            );
        }
        if (activeMinigame === 'podracing_bet' || activeMinigame === 'podracing_tracker') {
            return (
                <Podracing 
                    gameState={gameState}
                    mode={activeMinigame === 'podracing_bet' ? 'betting' : 'tracker'}
                    onClose={() => setActiveMinigame(null)}
                    onBetPlaced={(driverId, amount, isMain, startTime) => {
                        setGameState(prev => ({
                            ...prev,
                            credits: prev.credits - amount,
                            activeRace: {
                                type: isMain ? 'main' : 'rookie',
                                startTime: startTime,
                                betDriverId: driverId,
                                betAmount: amount,
                                completed: false
                            }
                        }));
                        // The component handles its own view transition to 'receipt'
                    }}
                    onRaceFinished={(winnerId, payout) => {
                        setActiveMinigame(null);
                        setGameState(prev => ({
                            ...prev,
                            credits: prev.credits + payout,
                            activeRace: { ...prev.activeRace!, completed: true }
                        }));
                        if (payout > 0) {
                            addToLog(`RACE UPDATE: Your driver won! You received ${payout} credits.`);
                        } else {
                            addToLog(`RACE UPDATE: Your driver lost. Better luck next time.`);
                        }
                    }}
                />
            );
        }
        return null;
    };

    return (
        <div className="flex flex-col md:flex-row h-full w-full max-w-7xl mx-auto md:p-4 gap-4 text-cyan-100 font-sans text-sm md:text-base">
            {renderMinigame()}

            {/* LEFT COLUMN - STATS */}
            <div className="w-full md:w-1/4 flex flex-col gap-4 order-2 md:order-1 h-1/4 md:h-full overflow-hidden">
                <div className="bg-gray-900/80 border border-cyan-700 p-4 rounded h-full overflow-y-auto no-scrollbar relative shadow-[0_0_15px_rgba(6,182,212,0.2)]">
                    <div className="scanline-overlay opacity-20" />
                    <h2 className="text-xl text-yellow-400 font-title border-b border-cyan-800 pb-2 mb-4">STATUS</h2>

                    <div className="mb-6 space-y-2">
                        <div className="flex justify-between"><span className="text-cyan-500">NAME:</span> <span>{gameState.stats?.name}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">CLASS:</span> <span>{gameState.stats?.charClass.name}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">CREDITS:</span> <span className="text-yellow-300">{gameState.credits}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">HEALTH:</span> <span className={`${gameState.stats?.currentHp! < 10 ? 'text-red-500 animate-pulse' : 'text-green-400'}`}>{gameState.stats?.currentHp} / {gameState.stats?.maxHp}</span></div>
                        <div className="flex justify-between"><span className="text-cyan-500">TIME:</span> <span>{isNight ? "Night Cycle" : "Day Cycle"}</span></div>
                    </div>

                    <h3 className="text-lg text-cyan-300 font-display border-b border-cyan-800 pb-1 mb-2">INVENTORY</h3>
                    <ul className="text-xs space-y-1 mb-6 font-mono text-gray-300">
                        {gameState.inventory.length === 0 && <li>Empty</li>}
                        {gameState.inventory.map((item, idx) => (
                            <li key={idx} className="flex justify-between">
                                <span>{item.name}</span>
                                {item.count > 1 && <span className="text-gray-500">x{item.count}</span>}
                            </li>
                        ))}
                    </ul>

                    <h3 className="text-lg text-cyan-300 font-display border-b border-cyan-800 pb-1 mb-2">ACTIVE QUESTS</h3>
                    <ul className="text-xs space-y-2 font-mono">
                        {gameState.quests.filter(q => q.status === 'active').length === 0 && <li className="text-gray-500">No active quests.</li>}
                        {gameState.quests.filter(q => q.status === 'active').map(q => (
                            <li key={q.id}>
                                <div className="text-yellow-200 mb-1">{q.title}</div>
                                <div className="text-gray-400 pl-2 border-l-2 border-gray-700">{q.steps[q.currentStepIndex].description}</div>
                            </li>
                        ))}
                    </ul>
                </div>
            </div>

            {/* CENTER COLUMN - VIEWPORT */}
            <div className="w-full md:w-2/4 flex flex-col gap-4 order-1 md:order-2 h-1/2 md:h-full">
                {/* Visual */}
                <div className="relative h-1/2 md:h-3/5 bg-black border-2 border-cyan-800 rounded overflow-hidden shadow-[0_0_20px_rgba(0,0,0,0.8)] group">
                    <img src={locImg} alt={locName} className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-gray-900 via-transparent to-transparent" />
                    <div className="scanline-overlay opacity-30" />

                    {/* Location Title Overlay */}
                    <div className="absolute bottom-4 left-4 right-4">
                        <h1 className="text-2xl md:text-3xl font-title text-transparent bg-clip-text bg-gradient-to-r from-cyan-300 to-blue-500 drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)]">{locName}</h1>
                    </div>

                    {/* NPC Overlays */}
                    <div className="absolute bottom-0 right-4 flex gap-4">
                        {locNpcs.filter(id => !gameState.defeatedNpcs?.includes(id)).map(npcId => {
                            const npc = NPC_DATABASE[npcId];
                            if(!npc) return null;
                            return (
                                <img 
                                    key={npcId} 
                                    src={npc.imageUrl} 
                                    className={`w-24 h-24 object-cover object-top border-2 border-transparent hover:border-yellow-400 rounded-t-lg transition-transform cursor-pointer hover:scale-105 ${currentNpcId === npcId ? 'border-yellow-400 scale-105 bg-black/50' : ''}`}
                                    onClick={() => startDialogue(npcId)}
                                    title={npc.name}
                                />
                            );
                        })}
                    </div>
                </div>

                {/* Log & Dialogue */}
                <div className="flex-1 bg-black/90 border border-gray-700 p-4 rounded font-mono text-sm md:text-base overflow-y-auto relative no-scrollbar" ref={scrollRef}>
                    {dialogueNode ? (
                        <div className="animate-fade-in">
                            <div className="text-yellow-400 mb-2 font-bold">{NPC_DATABASE[currentNpcId!].name}:</div>
                            <div className="text-white mb-6 p-3 bg-gray-800/50 rounded border-l-2 border-yellow-500">"{dialogueNode.text}"</div>
                            <div className="flex flex-col gap-2">
                                {dialogueNode.options.map((opt, idx) => {
                                    // Check requirements
                                    if (opt.reqSkill && gameState.stats && (gameState.stats.stats[opt.reqSkill] || 0) < (opt.reqVal || 0)) return null;
                                    if (opt.reqItem && !gameState.inventory.find(i => i.id === opt.reqItem)) return null;
                                    if (opt.reqQuestState) {
                                        const q = gameState.quests.find(q => q.id === opt.reqQuestState!.id);
                                        if(!q) return null;
                                        if (q.currentStepIndex !== opt.reqQuestState.step) return null; 
                                        // Simple exact step match for now
                                    }
                                    if (opt.reqTime && ((opt.reqTime === 'day' && isNight) || (opt.reqTime === 'night' && !isNight))) return null;

                                    return (
                                        <button 
                                            key={idx}
                                            onClick={() => handleDialogueOption(opt)}
                                            className="text-left text-cyan-400 hover:text-cyan-200 hover:bg-cyan-900/30 p-2 rounded transition-colors border border-transparent hover:border-cyan-700"
                                        >
                                            {idx + 1}. {opt.label}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-1 pb-4">
                            {gameState.history.map((line, i) => (
                                <div key={i} className={`break-words leading-relaxed ${line.startsWith('>') ? 'text-gray-400 italic' : line.startsWith('[COMBAT]') ? 'text-red-400' : 'text-gray-300'}`}>
                                    {i === gameState.history.length - 1 ? <Typewriter text={line} textKey={logKey} /> : line}
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            {/* RIGHT COLUMN - COMMANDS */}
            <div className="w-full md:w-1/4 flex flex-col gap-4 order-3 h-1/4 md:h-full overflow-hidden">
                <div className="bg-gray-900/80 border border-cyan-700 p-4 rounded h-full overflow-y-auto no-scrollbar shadow-[0_0_15px_rgba(6,182,212,0.2)]">
                    <div className="scanline-overlay opacity-20" />

                    {/* Navigation */}
                    <div className="mb-6">
                        <h3 className="text-cyan-500 font-display text-xs tracking-widest mb-3 border-b border-gray-700 pb-1">NAVIGATION</h3>
                        <div className="grid grid-cols-1 gap-2">
                            {locExits.map(exitId => {
                                const loc = locations[exitId];
                                if (!loc) return null;
                                return (
                                    <CommandButton 
                                        key={exitId} 
                                        label={`Go to ${loc.name}`} 
                                        onClick={() => handleMove(exitId)} 
                                        className="w-full text-left justify-start pl-4"
                                    />
                                );
                            })}
                        </div>
                    </div>

                    {/* Interactions */}
                    <div className="mb-6">
                        <h3 className="text-cyan-500 font-display text-xs tracking-widest mb-3 border-b border-gray-700 pb-1">INTERACTIONS</h3>
                        <div className="flex flex-col gap-2">
                            {/* General Actions */}
                            {locActions.map(action => (
                                <CommandButton key={action} label={action} onClick={() => handleAction(action)} />
                            ))}

                            {/* Searchables */}
                            {locSearchables.filter(s => {
                                // Hide if completed one-time searchables (simplified logic)
                                if (gameState.lootedContainers.includes(s.id) && !s.locked) return false;
                                return true;
                            }).map(s => (
                                <CommandButton 
                                    key={s.id} 
                                    label={`${s.locked && !gameState.unlockedContainers.includes(s.id) ? '🔒 ' : ''}${s.label}`} 
                                    onClick={() => handleSearch(s.id)} 
                                    className={`${s.locked && !gameState.unlockedContainers.includes(s.id) ? 'text-red-400 border-red-900/50 hover:bg-red-900/20' : ''}`}
                                />
                            ))}
                        </div>
                    </div>

                    {/* System */}
                    <div className="mt-auto pt-4 border-t border-gray-700 flex gap-2 justify-center">
                        <button onClick={onSave} className="text-xs text-gray-500 hover:text-white transition-colors">SAVE DATA</button>
                    </div>
                </div>
            </div>
        </div>
    );
}
